  font-style: normal;
  font-weight: 100 900;
  font-display: swap;
  src: url(assets/fonts/Onest-cyrillic.woff2) format('woff2');
  unicode-range: U+0301, U+0400-045F, U+0490-0491, U+04B0-04B1, U+2116;
