/* ============================================================
   ENHANCED ACCOUNTS + SUPPORT + FOOTER  (added)
   ============================================================ */

/* ---- Accounts header actions ---- */
.accounts-header-actions { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.acc-tool-btn {
    display: inline-flex; align-items: center; gap: 8px;
    padding: 11px 16px; border-radius: 13px; cursor: pointer;
    background: rgba(255,255,255,0.04);
    border: 1px solid rgba(255,255,255,0.10);
    color: #cbd5e1; font-size: 0.86rem; font-weight: 600;
    transition: color 0.25s var(--ease-smooth), background-color 0.25s var(--ease-smooth), border-color 0.25s var(--ease-smooth), transform 0.25s var(--ease-smooth);
}
.acc-tool-btn:hover {
    background: rgba(139,92,246,0.16);
    border-color: rgba(167,139,250,0.5);
    color: #fff; transform: translateY(-2px);
}
.acc-tool-btn i { font-size: 0.9rem; }

/* ---- Active account UUID chip ---- */
.active-account-uuid {
    display: inline-flex; align-items: center; gap: 7px; margin-top: 10px;
    padding: 5px 12px; border-radius: 10px; cursor: pointer;
    background: rgba(255,255,255,0.04); border: 1px solid rgba(255,255,255,0.08);
    color: #94a3b8; font-size: 0.74rem; font-family: 'Onest', monospace;
    letter-spacing: 0.3px; transition: color 0.22s ease, background-color 0.22s ease, border-color 0.22s ease; max-width: 320px;
}
.active-account-uuid span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.active-account-uuid:hover { color: #e2e8f0; border-color: rgba(167,139,250,0.45); background: rgba(139,92,246,0.12); }
.active-account-uuid.copied { color: #34d399; border-color: rgba(52,211,153,0.5); }

/* ---- Quick stats strip ---- */
.accounts-stats-strip {
    display: flex; align-items: center; justify-content: space-around;
    gap: 10px; margin: 22px 0 6px; padding: 18px 24px; flex-wrap: wrap;
    background: rgba(255,255,255,0.025);
    border: 1px solid rgba(255,255,255,0.07);
    border-radius: 18px; backdrop-filter: blur(14px);
}
.as-item { text-align: center; min-width: 90px; }
.as-num {
    font-size: 1.7rem; font-weight: 800; line-height: 1;
    background: linear-gradient(135deg, #a78bfa, #60a5fa);
    -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent;
}
.as-label { font-size: 0.74rem; color: var(--text-muted); margin-top: 6px; letter-spacing: 0.4px; }
.as-div { width: 1px; height: 34px; background: rgba(255,255,255,0.09); }

/* ---- Two-column layout: Minecraft profiles + Friends ---- */
.accounts-columns {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 22px;
    align-items: start;
    margin-top: 4px;
}

.acc-panel {
    background: rgba(255,255,255,0.03);
    border: 1px solid var(--glass-border);
    border-radius: 24px;
    padding: 26px;
}

/* section header inside each column, matching other tabs' card headers */
.acc-panel-head,
.acc-panel .friends-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 14px;
    flex-wrap: wrap;
    margin-bottom: 22px;
    padding-bottom: 18px;
    border-bottom: 1px solid var(--glass-border);
}
.acc-panel-head h3,
.acc-panel .friends-header h3 {
    font-size: 1.25rem;
    font-weight: 700;
    color: #fff;
    display: flex;
    align-items: center;
    gap: 10px;
}
.acc-panel-head h3 i { color: var(--primary); }

/* inside a column both lists become a clean single-column stack */
.acc-panel .accounts-grid,
.acc-panel .friends-grid,
.acc-panel .friend-requests { grid-template-columns: 1fr; }

/* friends block repurposed as a column panel (drop the old top divider) */
.acc-panel.friends-section { margin-top: 0; padding-top: 26px; border-top: none; }

body.light-theme .acc-panel { background: rgba(255,255,255,0.85); border-color: rgba(99,102,241,0.12); }
body.light-theme .acc-panel-head,
body.light-theme .acc-panel .friends-header { border-bottom-color: rgba(99,102,241,0.14); }
body.light-theme .acc-panel-head h3 { color: #1e1b4b; }

@media (max-width: 1000px) {
    .accounts-columns { grid-template-columns: 1fr; }
}

/* ---- Favorite star on cards ---- */
.acc-fav {
    position: absolute; top: 12px; right: 12px; z-index: 4;
    width: 30px; height: 30px; border-radius: 9px; cursor: pointer;
    display: flex; align-items: center; justify-content: center;
    background: rgba(0,0,0,0.25); border: 1px solid rgba(255,255,255,0.08);
    color: #6b7280; font-size: 0.82rem; transition: color 0.2s ease, background-color 0.2s ease, border-color 0.2s ease, transform 0.2s ease;
}
.acc-fav:hover { color: #fbbf24; border-color: rgba(251,191,36,0.5); transform: scale(1.08); }
.acc-fav.on { color: #fbbf24; border-color: rgba(251,191,36,0.55); background: rgba(251,191,36,0.14); }
.account-card { position: relative; }
.account-card.is-fav { border-color: rgba(251,191,36,0.35); }
/* reserve space in the header so the floating ACTIVE tag never overlaps the name */
