/* ============================================================
   SUPPORT SECTION
   ============================================================ */
.support-wrapper { max-width: 1100px; margin: 0 auto; padding: 20px 0 40px; }
.support-hero { text-align: center; margin-bottom: 44px; }
.support-badge {
    display: inline-flex; align-items: center; gap: 8px; margin-bottom: 18px;
    padding: 7px 16px; border-radius: 30px; font-size: 0.8rem; font-weight: 600;
    background: rgba(16,185,129,0.12); border: 1px solid rgba(16,185,129,0.3); color: #34d399;
}
.support-hero h2 { font-size: clamp(2rem, 5vw, 3.2rem); font-weight: 800; line-height: 1.1; margin-bottom: 16px; }
.support-hero p { color: var(--text-muted); max-width: 620px; margin: 0 auto; font-size: 1.05rem; line-height: 1.6; }

.support-channels { display: grid; grid-template-columns: repeat(3, 1fr); gap: 18px; margin-bottom: 50px; }
.support-channel {
    display: flex; align-items: center; gap: 16px; padding: 20px 22px; border-radius: 18px;
    background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.08);
    text-decoration: none; color: inherit; transition: background-color 0.28s var(--ease-smooth), border-color 0.28s var(--ease-smooth), transform 0.28s var(--ease-smooth);
    position: relative; overflow: hidden;
}
.support-channel::before {
    content: ''; position: absolute; top: 0; left: 0; right: 0; height: 2px;
    background: var(--ch); opacity: 0; transition: opacity 0.28s var(--ease-smooth);
}
.support-channel:hover { transform: translateY(-4px); border-color: color-mix(in srgb, var(--ch) 55%, transparent); background: color-mix(in srgb, var(--ch) 10%, rgba(255,255,255,0.03)); }
.support-channel:hover::before { opacity: 0.85; }
.sc-icon {
    width: 50px; height: 50px; border-radius: 14px; flex-shrink: 0;
    display: flex; align-items: center; justify-content: center; font-size: 1.4rem;
    color: var(--ch); background: color-mix(in srgb, var(--ch) 16%, transparent);
    border: 1px solid color-mix(in srgb, var(--ch) 35%, transparent);
}
.sc-body h4 { font-size: 1.02rem; font-weight: 700; margin-bottom: 3px; }
.sc-body p { color: var(--text-muted); font-size: 0.85rem; }
.sc-arrow { margin-left: auto; color: var(--text-muted); font-size: 0.85rem; transition: color 0.25s ease, transform 0.25s ease; }
.support-channel:hover .sc-arrow { color: var(--ch); transform: translate(2px,-2px); }

.support-subtitle { font-size: 1.5rem; font-weight: 700; margin: 8px 0 22px; }

.support-fixes { display: grid; grid-template-columns: repeat(3, 1fr); gap: 18px; margin-bottom: 50px; }
.fix-card { padding: 24px; border-radius: 18px; transition: border-color 0.3s ease, box-shadow 0.4s var(--ease-smooth); }
.fix-card:hover { border-color: rgba(99,102,241,0.3); box-shadow: 0 14px 40px rgba(99,102,241,0.10); }
/* icon tile tinted by the per-card colour (set inline on .fix-icon) */
.fix-icon { width: 48px; height: 48px; border-radius: 13px; display: flex; align-items: center; justify-content: center; font-size: 1.3rem; background: color-mix(in srgb, currentColor 15%, transparent); border: 1px solid color-mix(in srgb, currentColor 32%, transparent); margin-bottom: 16px; }
.fix-card h4 { font-size: 1.05rem; font-weight: 700; margin-bottom: 10px; }
.fix-card p { color: var(--text-muted); font-size: 0.9rem; line-height: 1.6; }
.fix-card code { background: rgba(96,165,250,0.16); color: #93c5fd; padding: 1px 6px; border-radius: 5px; font-size: 0.85em; }

/* FAQ accordion */
.faq-list { display: flex; flex-direction: column; gap: 12px; margin-bottom: 50px; }
.faq-item {
    background: rgba(255,255,255,0.025); border: 1px solid rgba(255,255,255,0.07);
    border-radius: 15px; overflow: hidden; transition: border-color 0.25s ease, background 0.25s ease;
}
.faq-item.open { border-color: rgba(167,139,250,0.4); background: rgba(139,92,246,0.06); }
.faq-q {
    width: 100%; text-align: left; cursor: pointer; border: none; background: transparent;
    color: #e2e8f0; font-family: 'Onest'; font-size: 1rem; font-weight: 600;
    padding: 19px 22px; display: flex; align-items: center; justify-content: space-between; gap: 16px;
}
.faq-q i { color: var(--text-muted); font-size: 0.85rem; transition: transform 0.3s var(--ease-smooth); flex-shrink: 0; }
.faq-item.open .faq-q i { transform: rotate(180deg); color: #a78bfa; }
.faq-a { max-height: 0; overflow: hidden; transition: max-height 0.42s cubic-bezier(0.4, 0, 0.2, 1); }
.faq-a p { padding: 0 22px 20px; color: var(--text-muted); font-size: 0.92rem; line-height: 1.65; }

/* CTA */
.support-cta {
    position: relative; overflow: hidden;
    display: flex; align-items: center; justify-content: space-between; gap: 24px; flex-wrap: wrap;
    padding: 32px 38px; border-radius: 22px;
    background: linear-gradient(120deg, rgba(139,92,246,0.16), rgba(96,165,250,0.10));
    border: 1px solid rgba(167,139,250,0.28);
}
.support-cta-glow { position: absolute; inset: 0; background: radial-gradient(circle at 80% 20%, rgba(139,92,246,0.25), transparent 60%); pointer-events: none; }
.support-cta h3 { font-size: 1.5rem; font-weight: 800; margin-bottom: 6px; position: relative; }
.support-cta p { color: #cbd5e1; position: relative; }
.support-cta .btn-primary { position: relative; }

/* ============================================================
   FOOTER
   ============================================================ */
.site-footer {
    position: relative; z-index: 2; margin-top: 40px;
    border-top: 1px solid rgba(255,255,255,0.07);
    background: rgba(8,8,12,0.6); backdrop-filter: blur(12px);
}
.footer-inner {
    max-width: 1200px; margin: 0 auto; padding: 36px 40px 24px;
    display: flex; align-items: center; justify-content: space-between; gap: 24px; flex-wrap: wrap;
}
.footer-brand { display: flex; align-items: center; gap: 14px; }
.footer-logo { width: 42px; height: 42px; border-radius: 11px; }
.footer-name { font-weight: 800; font-size: 1.05rem; }
.footer-tag { color: var(--text-muted); font-size: 0.82rem; }
.footer-links { display: flex; gap: 8px; flex-wrap: wrap; }
.footer-links a { color: #94a3b8; text-decoration: none; font-size: 0.88rem; font-weight: 600; padding: 7px 12px; border-radius: 10px; transition: color 0.2s ease, background-color 0.2s ease; cursor: pointer; }
.footer-links a:hover { color: #fff; background: rgba(255,255,255,0.06); }
.footer-social { display: flex; gap: 10px; }
.footer-social a {
    width: 40px; height: 40px; border-radius: 11px; display: flex; align-items: center; justify-content: center;
    background: rgba(255,255,255,0.04); border: 1px solid rgba(255,255,255,0.08); color: #cbd5e1;
    text-decoration: none; transition: color 0.25s ease, background-color 0.25s ease, border-color 0.25s ease, transform 0.25s ease;
}
.footer-social a:hover { color: #fff; transform: translateY(-2px); border-color: rgba(167,139,250,0.5); background: rgba(139,92,246,0.16); }
.footer-bottom { text-align: center; color: #6b7280; font-size: 0.8rem; padding: 16px 20px 26px; border-top: 1px solid rgba(255,255,255,0.04); }

/* ---- Responsive ---- */
@media (max-width: 860px) {
    .support-channels, .support-fixes { grid-template-columns: 1fr; }
    .footer-inner { flex-direction: column; text-align: center; }
}

/* ============================================================
   ROLE BADGES
   ============================================================ */
.role-badge { display:inline-flex; align-items:center; gap:5px; padding:2px 10px; border-radius:12px; font-size:0.62rem; font-weight:700; margin-left:6px; text-transform:uppercase; letter-spacing:0.3px; color:#fff; }
.role-badge i { font-size:0.7em; }
.role-veteran  { background:linear-gradient(135deg,#14b8a6,#0d9488); }
.role-pro      { background:linear-gradient(135deg,#f59e0b,#d97706); color:#1a1205; }
.role-moderator{ background:linear-gradient(135deg,#3b82f6,#2563eb); }
.role-admin    { background:linear-gradient(135deg,#ef4444,#dc2626); }
.role-dev      { background:linear-gradient(135deg,#ec4899,#f43f5e); }
.role-banned   { background:rgba(120,120,130,0.35); color:#e5e7eb; }
.role-user     { background:rgba(255,255,255,0.1); color:#aaa; }

/* ============================================================
   LAUNCHER NOTICE (Accounts tab — not signed in)
   ============================================================ */
.launcher-notice {
    display: flex; align-items: center; gap: 20px; flex-wrap: wrap;
    padding: 22px 28px; border-radius: 20px; margin-bottom: 30px;
    border: 1px solid rgba(99,102,241,0.25);
    background: rgba(99,102,241,0.06);
}
.ln-icon {
    width: 50px; height: 50px; border-radius: 14px; flex-shrink: 0;
    display: flex; align-items: center; justify-content: center;
    font-size: 1.4rem; color: var(--primary);
    background: rgba(99,102,241,0.12); border: 1px solid rgba(99,102,241,0.3);
}
.ln-body { flex: 1; }
.ln-body strong { display:block; color:#e2e8f0; font-size:0.95rem; margin-bottom:4px; }
.ln-body span { color: var(--text-muted); font-size:0.85rem; line-height:1.5; }
.ln-signin-btn {
    padding: 10px 22px; border-radius: 12px; cursor: pointer;
    background: var(--primary); color: #fff; border: none;
    font-weight: 700; font-size: 0.88rem; white-space: nowrap;
    display: inline-flex; align-items: center; gap: 8px;
    transition: background 0.2s ease, transform 0.2s ease;
}
.ln-signin-btn:hover { background: #4f46e5; transform: scale(1.03); }

/* ============================================================
   DEV WRITE UPDATE BUTTON
   ============================================================ */
.dev-write-btn {
    display: inline-flex; align-items: center; gap: 10px;
    padding: 12px 22px; border-radius: 14px; cursor: pointer;
    background: rgba(236,72,153,0.12); border: 1px solid rgba(236,72,153,0.4);
    color: #ec4899; font-weight: 700; font-size: 0.9rem;
    transition: background-color 0.25s var(--ease-smooth), transform 0.25s var(--ease-smooth);
}
.dev-write-btn:hover { background: rgba(236,72,153,0.22); transform: translateY(-2px); }

/* ============================================================
   DASHBOARD — SITE ACCOUNT REDESIGN
   ============================================================ */
.auth-sub { color: var(--text-muted); font-size: 0.85rem; text-align: center; margin-bottom: 1.5rem; line-height: 1.5; }
.auth-switch { text-align: center; margin-top: 1rem; color: var(--text-muted); font-size: 0.85rem; }
.auth-error {
    background: rgba(239,68,68,0.1); border: 1px solid rgba(239,68,68,0.3);
    color: #fca5a5; padding: 10px 14px; border-radius: 10px;
    font-size: 0.85rem; margin-bottom: 14px; text-align: center;
}
.link-btn {
    background: none; border: none; color: var(--primary); cursor: pointer;
    font-size: 0.85rem; font-weight: 700; padding: 0 2px;
    text-decoration: underline; transition: color 0.2s ease;
}
.link-btn:hover { color: #818cf8; }

/* Informational (non-error) note under auth forms */
.auth-note {
    background: rgba(16,185,129,0.1); border: 1px solid rgba(16,185,129,0.3);
    color: #6ee7b7; padding: 10px 14px; border-radius: 10px;
    font-size: 0.83rem; margin-bottom: 14px; text-align: center; line-height: 1.45;
}

/* Google sign-in button */
.btn-google {
    width: 100%; display: flex; align-items: center; justify-content: center; gap: 10px;
    padding: 12px 16px; border-radius: 12px; cursor: pointer;
    font-family: 'Onest'; font-size: 0.9rem; font-weight: 700;
    background: #fff; color: #1f2937; border: 1px solid rgba(0,0,0,0.1);
    transition: transform 0.15s ease, box-shadow 0.2s ease, background 0.2s ease;
}
.btn-google:hover { background: #f3f4f6; transform: translateY(-1px); box-shadow: 0 6px 18px rgba(0,0,0,0.25); }
.btn-google svg { flex-shrink: 0; }

/* "or" divider between Google and email forms */
.auth-divider {
    display: flex; align-items: center; gap: 12px;
    margin: 16px 0; color: var(--text-muted); font-size: 0.78rem; text-transform: uppercase; letter-spacing: 1px;
}
.auth-divider::before, .auth-divider::after {
    content: ''; flex: 1; height: 1px; background: rgba(255,255,255,0.12);
}
body.light-theme .auth-divider::before, body.light-theme .auth-divider::after { background: rgba(99,102,241,0.18); }
body.light-theme .btn-google { background: #fff; color: #1f2937; }

/* Profile tabs */
.profile-tabs {
    display: flex; gap: 6px; margin-bottom: 24px;
    background: rgba(255,255,255,0.04); border-radius: 14px; padding: 5px;
    border: 1px solid rgba(255,255,255,0.07);
}
.profile-tab {
    flex: 1; padding: 9px 10px; border: none; border-radius: 10px;
    background: transparent; color: var(--text-muted);
    font-size: 0.82rem; font-weight: 600; cursor: pointer;
    display: flex; align-items: center; justify-content: center; gap: 7px;
    transition: color 0.2s ease, background-color 0.2s ease;
}
.profile-tab:hover { color: #fff; background: rgba(255,255,255,0.06); }
.profile-tab.active { background: rgba(99,102,241,0.2); color: #818cf8; }
.ptab-content { animation: fadeInUp 0.25s var(--ease-out-back); }

/* Launcher info card (inside dashboard) */
.launcher-info-card {
    text-align: center; padding: 24px 10px;
}
.lic-icon {
    width: 64px; height: 64px; border-radius: 18px; margin: 0 auto 16px;
    display: flex; align-items: center; justify-content: center;
    font-size: 1.8rem; color: var(--primary);
    background: rgba(99,102,241,0.1); border: 1px solid rgba(99,102,241,0.25);
}
.launcher-info-card h4 { font-size: 1.15rem; font-weight: 700; margin-bottom: 8px; }
.lic-count { font-size: 2rem; font-weight: 900; color: var(--primary); margin-bottom: 10px; }
.launcher-info-card p { color: var(--text-muted); font-size: 0.88rem; line-height: 1.5; margin-bottom: 16px; }
.lic-go-btn {
    padding: 11px 24px; border-radius: 12px; border: none; cursor: pointer;
    background: rgba(99,102,241,0.15); color: var(--primary);
    border: 1px solid rgba(99,102,241,0.3); font-weight: 700; font-size: 0.88rem;
    display: inline-flex; align-items: center; gap: 8px;
    transition: background-color 0.2s ease;
}
.lic-go-btn:hover { background: rgba(99,102,241,0.28); }

/* ============================================================
   ADMIN PANEL (inside dashboard)
   ============================================================ */
.admin-panel-wrap { padding-top: 4px; }
.admin-subtabs {
    display: flex; gap: 6px; margin-bottom: 18px;
    background: rgba(255,255,255,0.03); border-radius: 12px; padding: 4px;
    border: 1px solid rgba(255,255,255,0.06);
}
.admin-stab {
    flex: 1; padding: 8px 8px; border: none; border-radius: 9px;
    background: transparent; color: var(--text-muted);
    font-size: 0.78rem; font-weight: 600; cursor: pointer;
    display: flex; align-items: center; justify-content: center; gap: 6px;
    transition: color 0.2s ease, background-color 0.2s ease;
}
.admin-stab:hover { color: #fff; background: rgba(255,255,255,0.06); }
.admin-stab.active { background: rgba(239,68,68,0.18); color: #f87171; }
.admin-stab-content { animation: fadeInUp 0.22s var(--ease-out-back); }

.admin-search-input {
    width: 100%; padding: 10px 14px; border-radius: 12px; outline: none;
    background: rgba(255,255,255,0.04); border: 1px solid rgba(255,255,255,0.10);
    color: #e2e8f0; font-size: 0.88rem; font-family: 'Onest'; margin-bottom: 14px;
    transition: border-color 0.2s ease;
}
.admin-search-input:focus { border-color: rgba(239,68,68,0.5); }

.admin-user-row {
    display: flex; align-items: center; gap: 14px;
    padding: 12px 14px; border-radius: 12px; margin-bottom: 8px;
    background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.06);
    transition: border-color 0.2s ease;
}
.admin-user-row:hover { border-color: rgba(255,255,255,0.12); }
.admin-user-avatar { width:38px; height:38px; border-radius:10px; image-rendering:pixelated; flex-shrink:0; }
.admin-user-name { flex:1; font-weight:700; font-size:0.9rem; }
.admin-user-bio { color:var(--text-muted); font-size:0.75rem; margin-top:2px; }
.admin-role-select {
    padding: 5px 10px; border-radius: 9px; border: none; outline: none;
    background: rgba(255,255,255,0.07); color: #e2e8f0;
    font-size: 0.78rem; font-weight: 600; font-family: 'Onest'; cursor: pointer;
}
.admin-role-select option { background: #1a1a20; }

.admin-stats-grid {
    display: grid; grid-template-columns: 1fr 1fr; gap: 12px;
}
.admin-stat-box {
    background: rgba(255,255,255,0.04); border: 1px solid rgba(255,255,255,0.08);
    border-radius: 14px; padding: 18px; text-align: center;
}
.admin-stat-val { font-size: 2rem; font-weight: 900; color: var(--primary); line-height: 1; }
.admin-stat-label { font-size: 0.78rem; color: var(--text-muted); margin-top: 6px; }

/* ── Extended admin: search row, user rows, actions ── */
.admin-search-wrap { display:flex; gap:10px; margin-bottom:14px; align-items:center; }
.admin-search-wrap .admin-search-input { margin-bottom:0; flex:1; }
.admin-role-filter {
    padding:10px 12px; border-radius:12px; outline:none; cursor:pointer;
    background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.10);
    color:#e2e8f0; font-size:0.84rem; font-family:'Onest'; font-weight:600;
}
.admin-role-filter option { background:#1a1a20; }
.admin-user-main { flex:1; min-width:0; }
.admin-user-name { flex:0; font-weight:700; font-size:0.9rem; display:flex; align-items:center; flex-wrap:wrap; gap:4px; }
.admin-user-stats { display:flex; flex-wrap:wrap; gap:12px; margin-top:5px; font-size:0.72rem; color:#94a3b8; }
.admin-user-stats i { margin-right:3px; opacity:0.8; }
.admin-user-controls { display:flex; flex-direction:column; align-items:flex-end; gap:7px; flex-shrink:0; }
.admin-user-actions { display:flex; gap:6px; }
.admin-act-btn {
    padding:5px 10px; border-radius:8px; cursor:pointer; font-size:0.74rem; font-weight:700;
    font-family:'Onest'; border:1px solid transparent; transition:background-color 0.18s ease;
    display:inline-flex; align-items:center; gap:5px;
}
.admin-act-btn.ban   { background:rgba(245,158,11,0.14); color:#fbbf24; border-color:rgba(245,158,11,0.3); }
.admin-act-btn.ban:hover   { background:rgba(245,158,11,0.26); }
.admin-act-btn.unban { background:rgba(16,185,129,0.14); color:#34d399; border-color:rgba(16,185,129,0.3); }
.admin-act-btn.unban:hover { background:rgba(16,185,129,0.26); }
.admin-act-btn.del   { background:rgba(239,68,68,0.14); color:#f87171; border-color:rgba(239,68,68,0.3); }
.admin-act-btn.del:hover   { background:rgba(239,68,68,0.28); }
.admin-user-row.is-banned { opacity:0.6; border-color:rgba(239,68,68,0.25); }
.admin-empty { color:var(--text-muted); font-size:0.85rem; text-align:center; padding:18px; }

/* ── Stat boxes with icon + secondary grid ── */
.admin-stat-ico { font-size:1.1rem; color:var(--primary); margin-bottom:8px; opacity:0.85; }
.admin-stats-grid.secondary { grid-template-columns:repeat(4,1fr); gap:10px; margin-top:14px; }
.admin-stat-box.sm { padding:12px 10px; }
.admin-stat-box.sm .admin-stat-val { font-size:1.3rem; color:#e2e8f0; }
.admin-stat-box.sm .admin-stat-label { font-size:0.68rem; }

/* ── DEV analytics panels ── */
.dev-panels { display:grid; grid-template-columns:1fr 1fr; gap:14px; margin-top:18px; }
.dev-card {
    background:rgba(255,255,255,0.03); border:1px solid rgba(255,255,255,0.08);
    border-radius:14px; padding:16px;
}
.dev-card h4 { font-size:0.82rem; font-weight:800; margin:0 0 12px; display:flex; align-items:center; gap:8px; color:#e2e8f0; }
.dev-card h4 i { color:var(--primary); }
.dist-row { display:flex; align-items:center; gap:10px; margin-bottom:9px; font-size:0.76rem; }
.dist-label { width:104px; flex-shrink:0; color:#cbd5e1; display:flex; align-items:center; gap:6px; white-space:nowrap; }
.dist-bar { flex:1; height:8px; border-radius:6px; background:rgba(255,255,255,0.07); overflow:hidden; }
.dist-fill { height:100%; border-radius:6px; transition:width 0.5s var(--ease-out-back); min-width:2px; }
.dist-val { width:28px; text-align:right; font-weight:700; color:#e2e8f0; flex-shrink:0; }
.lead-row { display:flex; align-items:center; gap:9px; padding:6px 0; font-size:0.78rem; border-bottom:1px solid rgba(255,255,255,0.05); }
.lead-row:last-child { border-bottom:none; }
.lead-rank { width:24px; font-weight:800; color:var(--primary); }
.lead-av { width:26px; height:26px; border-radius:7px; image-rendering:pixelated; flex-shrink:0; }
.lead-name { flex:1; display:flex; align-items:center; gap:5px; min-width:0; overflow:hidden; }
.lead-time { font-weight:700; color:#94a3b8; white-space:nowrap; }

/* ── DEV tools ── */
.dev-tools { margin-top:18px; padding:16px; border-radius:14px; background:rgba(236,72,153,0.05); border:1px solid rgba(236,72,153,0.2); }
.dev-tools h4 { font-size:0.82rem; font-weight:800; margin:0 0 12px; display:flex; align-items:center; gap:8px; color:#f472b6; }
.dev-tools-row { display:flex; flex-wrap:wrap; gap:10px; }
.dev-tool-btn {
    padding:9px 14px; border-radius:10px; cursor:pointer; font-size:0.8rem; font-weight:700;
    font-family:'Onest'; display:inline-flex; align-items:center; gap:7px; transition:background-color 0.18s ease;
    background:rgba(255,255,255,0.06); color:#e2e8f0; border:1px solid rgba(255,255,255,0.12);
}
.dev-tool-btn:hover { background:rgba(255,255,255,0.12); }
.dev-tool-btn.danger { background:rgba(239,68,68,0.12); color:#f87171; border-color:rgba(239,68,68,0.3); }
.dev-tool-btn.danger:hover { background:rgba(239,68,68,0.24); }
.dev-tools-note { font-size:0.72rem; color:var(--text-muted); margin:12px 0 0; }
.dev-tools-note code { background:rgba(255,255,255,0.08); padding:2px 7px; border-radius:6px; color:#34d399; }

/* Light theme readability for the new panels */
body.light-theme .admin-user-stats { color:#6366a0; }
body.light-theme .dev-card { background:rgba(255,255,255,0.85); border-color:rgba(99,102,241,0.12); }
body.light-theme .dev-card h4, body.light-theme .dist-val, body.light-theme .admin-stat-box.sm .admin-stat-val { color:#1e1b4b; }
body.light-theme .dist-label { color:#4b4f80; }
body.light-theme .dev-tool-btn { background:rgba(99,102,241,0.08); color:#1e1b4b; border-color:rgba(99,102,241,0.2); }

/* Responsive */
@media (max-width:560px){
    .dev-panels { grid-template-columns:1fr; }
    .admin-stats-grid.secondary { grid-template-columns:1fr 1fr; }
    .admin-user-controls { flex-direction:row; align-items:center; flex-wrap:wrap; }
    .admin-search-wrap { flex-direction:column; align-items:stretch; }
}

/* Forum items in admin panel */
.admin-forum-item {
    padding: 12px 14px; border-radius: 12px; margin-bottom: 8px;
    background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.06);
}
.admin-forum-title { font-weight: 700; font-size: 0.88rem; margin-bottom: 4px; }
.admin-forum-meta { color: var(--text-muted); font-size: 0.74rem; margin-bottom: 8px; }
.admin-forum-actions { display: flex; gap: 8px; }
.admin-forum-approve {
    padding: 5px 12px; border-radius: 8px; border: none; cursor: pointer; font-size: 0.78rem; font-weight: 700;
    background: rgba(16,185,129,0.15); color: #34d399; border: 1px solid rgba(16,185,129,0.3);
    transition: background-color 0.2s ease;
}
.admin-forum-approve:hover { background: rgba(16,185,129,0.28); }
.admin-forum-reject {
    padding: 5px 12px; border-radius: 8px; border: none; cursor: pointer; font-size: 0.78rem; font-weight: 700;
    background: rgba(239,68,68,0.12); color: #f87171; border: 1px solid rgba(239,68,68,0.3);
    transition: background-color 0.2s ease;
}
.admin-forum-reject:hover { background: rgba(239,68,68,0.25); }
.admin-forum-status {
    font-size: 0.72rem; font-weight: 700; padding: 3px 8px; border-radius: 8px; margin-left: auto;
}
.afs-pending { background: rgba(245,158,11,0.15); color: #fbbf24; }
.afs-approved { background: rgba(16,185,129,0.15); color: #34d399; }
.afs-rejected { background: rgba(239,68,68,0.15); color: #f87171; }

/* ============================================================
   NEWS EDITOR MODAL
   ============================================================ */
.news-items-editor { margin: 4px 0 10px; }
.nie-label { font-size: 0.78rem; text-transform: uppercase; letter-spacing: 1px; color: var(--text-muted); margin-bottom: 10px; }
.news-item-row {
    display: flex; gap: 8px; align-items: center; margin-bottom: 8px;
}
.nie-type {
    padding: 9px 10px; border-radius: 10px; border: 1px solid rgba(255,255,255,0.1);
    background: rgba(255,255,255,0.05); color: #e2e8f0; font-family: 'Onest'; font-size: 0.82rem;
    outline: none; cursor: pointer; flex-shrink: 0; width: 120px;
}
.nie-type option { background: #1a1a20; }
.nie-text {
    flex: 1; padding: 9px 12px; border-radius: 10px; border: 1px solid rgba(255,255,255,0.1);
    background: rgba(255,255,255,0.04); color: #e2e8f0; font-family: 'Onest'; font-size: 0.88rem; outline: none;
