}
.nie-text:focus { border-color: rgba(99,102,241,0.5); }
.nie-remove {
    width: 32px; height: 32px; border-radius: 9px; border: none; cursor: pointer; flex-shrink: 0;
    background: rgba(239,68,68,0.1); color: #f87171; display: flex; align-items: center; justify-content: center;
    font-size: 0.85rem; transition: background-color 0.2s ease;
}
.nie-remove:hover { background: rgba(239,68,68,0.25); }
.nie-add-btn {
    padding: 8px 16px; border-radius: 10px; border: 1px dashed rgba(99,102,241,0.4);
    background: transparent; color: var(--primary); font-size: 0.85rem; font-weight: 600;
    cursor: pointer; display: inline-flex; align-items: center; gap: 6px;
    transition: background-color 0.2s ease;
}
.nie-add-btn:hover { background: rgba(99,102,241,0.1); }

/* ============================================================
   FORUM SECTION (Support tab)
   ============================================================ */
.forum-section { margin-top: 64px; padding-top: 20px; border-top: 1px solid rgba(255,255,255,0.07); }
.forum-header-row {
    display: flex; align-items: flex-end; justify-content: space-between; gap: 20px;
    margin-bottom: 28px; flex-wrap: wrap;
}
.forum-write-btn {
    padding: 11px 22px; border-radius: 14px; border: none; cursor: pointer;
    background: linear-gradient(135deg, rgba(245,158,11,0.2), rgba(217,119,6,0.15));
    border: 1px solid rgba(245,158,11,0.4); color: #fbbf24;
    font-weight: 700; font-size: 0.9rem;
    display: inline-flex; align-items: center; gap: 8px;
    transition: background-color 0.25s var(--ease-smooth), transform 0.25s var(--ease-smooth); flex-shrink: 0;
}
.forum-write-btn:hover { background: rgba(245,158,11,0.25); transform: translateY(-2px); }
.forum-write-wrap { display: flex; flex-direction: column; align-items: flex-end; gap: 6px; flex-shrink: 0; }
.forum-write-btn.locked { opacity: 0.75; }
.forum-login-hint {
    display: inline-flex; align-items: center; gap: 6px;
    font-size: 0.74rem; font-weight: 600; color: #fbbf24;
}
.forum-login-hint i { font-size: 0.7em; opacity: 0.85; }
.forum-login-hint { cursor: pointer; }

/* Ideas laid out as a responsive 2-column masonry-style grid */
.forum-posts-list {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 16px;
    align-items: start;
}
.forum-post-card {
    background: rgba(14,14,18,0.8); border: 1px solid rgba(255,255,255,0.07);
    border-radius: 18px; padding: 22px 24px;
    transition: border-color 0.25s ease, transform 0.3s var(--ease-smooth), box-shadow 0.4s var(--ease-smooth);
}
