.forum-post-card.pending { border-color: rgba(245,158,11,0.25); background: rgba(245,158,11,0.04); }

.fp-header { display: flex; align-items: flex-start; gap: 12px; margin-bottom: 10px; }
.fp-avatar { width: 36px; height: 36px; border-radius: 10px; image-rendering: pixelated; flex-shrink: 0; }
.fp-meta { flex: 1; }
.fp-author { font-size: 0.82rem; color: var(--text-muted); margin-bottom: 2px; }
.fp-title { font-size: 1rem; font-weight: 700; color: #e2e8f0; }
.fp-status {
    font-size: 0.7rem; font-weight: 700; padding: 3px 8px; border-radius: 8px; flex-shrink: 0; align-self: flex-start;
}
.fp-pending { background: rgba(245,158,11,0.15); color: #fbbf24; }
.fp-text { color: var(--text-muted); font-size: 0.88rem; line-height: 1.6; margin-bottom: 14px; }
.fp-footer { display: flex; align-items: center; gap: 12px; }
.fp-upvote {
    display: inline-flex; align-items: center; gap: 7px;
    padding: 6px 14px; border-radius: 10px; cursor: pointer; border: none;
    background: rgba(255,255,255,0.05); border: 1px solid rgba(255,255,255,0.1);
    color: var(--text-muted); font-size: 0.82rem; font-weight: 600;
    transition: color 0.2s ease, background-color 0.2s ease, border-color 0.2s ease;
}
.fp-upvote:hover { color: #818cf8; border-color: rgba(99,102,241,0.4); background: rgba(99,102,241,0.1); }
.fp-upvote.voted { color: #818cf8; border-color: rgba(99,102,241,0.5); background: rgba(99,102,241,0.15); }
.fp-date { color: var(--text-muted); font-size: 0.76rem; margin-left: auto; }

.forum-empty-state {
    text-align: center; padding: 60px 20px; color: var(--text-muted);
}
.forum-empty-state i { font-size: 3rem; opacity: 0.2; display: block; margin-bottom: 14px; }

/* Forum post modal textarea */
.forum-textarea-wrap { position: relative; margin-bottom: 18px; }
.forum-textarea-label { display: block; font-size: 0.78rem; color: var(--text-muted); margin-bottom: 8px; text-transform: uppercase; letter-spacing: 0.5px; }
#forumPostText {
    width: 100%; padding: 12px 14px; border-radius: 12px; border: 1px solid rgba(255,255,255,0.1);
    background: #18181b; color: #e2e8f0; font-family: 'Onest'; font-size: 0.92rem;
    resize: vertical; outline: none; min-height: 100px;
    transition: border-color 0.2s ease;
}
#forumPostText:focus { border-color: rgba(99,102,241,0.5); }
.forum-char-count { text-align: right; font-size: 0.76rem; color: var(--text-muted); margin-top: 5px; }
.forum-char-count span { color: #e2e8f0; }

/* ============================================================
   UPDATES TIMELINE — DEV-EDITABLE
   ============================================================ */
.timeline-delete-btn {
    width: 28px; height: 28px; border-radius: 8px; border: none; cursor: pointer;
    background: rgba(239,68,68,0.1); color: #f87171; font-size: 0.75rem;
    display: flex; align-items: center; justify-content: center;
