/* Nav avatar with image */
#navAvatarCircle img {
    width: 100%; height: 100%; border-radius: 50%; object-fit: cover;
}

/* ============================================================
   THEME FAB (fixed bottom-right)
   ============================================================ */
.theme-fab {
    position: fixed;
    bottom: 92px;
    right: 30px;
    width: 50px; height: 50px;
    border-radius: 50%;
    background: rgba(99,102,241,0.18);
    border: 1px solid rgba(99,102,241,0.35);
    color: #a5b4fc;
    cursor: pointer;
    display: flex; align-items: center; justify-content: center;
    font-size: 1.1rem;
    z-index: 998;
    box-shadow: 0 4px 20px rgba(99,102,241,0.25);
    transition: transform 0.35s var(--ease-out-back), background 0.25s ease, box-shadow 0.25s ease;
}
.theme-fab:hover {
    background: rgba(99,102,241,0.3);
    transform: scale(1.12) rotate(22deg);
    box-shadow: 0 6px 28px rgba(99,102,241,0.4);
}

/* ============================================================
   SMOOTH THEME TRANSITION
   ============================================================ */
body.theme-switching { transition: background-color 0.45s ease, color 0.35s ease; }

/* ============================================================
   LIGHT THEME — proper design, not inversion
   ============================================================ */
body.light-theme {
    --bg-dark:       #dfe3f7;
    --glass-bg:      rgba(255, 255, 255, 0.82);
    --glass-border:  rgba(99, 102, 241, 0.16);
    --text:          #1e1b4b;
    --text-muted:    #5b5f93;
    color: var(--text);
    /* distinct light background: soft diagonal gradient base */
    background: linear-gradient(155deg, #eaecfc 0%, #dfe4f8 40%, #ece6f9 72%, #e6ecfb 100%);
    background-attachment: fixed;
}

/* Colorful aurora mesh — gives depth so white cards pop (different from dark theme) */
body.light-theme #particles-canvas { opacity: 0.5; }
body.light-theme .bg-gradient-overlay {
    background:
        radial-gradient(42% 50% at 14% 10%, rgba(129,140,248,0.40), transparent 70%),
        radial-gradient(40% 46% at 88% 16%, rgba(96,165,250,0.34), transparent 70%),
        radial-gradient(46% 52% at 80% 88%, rgba(236,72,153,0.22), transparent 72%),
        radial-gradient(42% 48% at 16% 84%, rgba(45,212,191,0.22), transparent 72%);
    opacity: 1;
}
body.light-theme .vignette {
    background: radial-gradient(circle, transparent 55%, rgba(150,160,220,0.22) 100%);
}
body.light-theme .ambient-light { opacity: 0.22; mix-blend-mode: multiply; }

/* ── Light-theme drifting orbs (hidden on dark) ── */
.light-bg-shapes { display: none; }
body.light-theme .light-bg-shapes {
    display: block;
    position: fixed;
    inset: 0;
    z-index: -1;
    pointer-events: none;
    overflow: hidden;
}
.light-bg-shapes .lbs {
    position: absolute;
    border-radius: 50%;
    filter: blur(50px);
    mix-blend-mode: multiply;
    opacity: 0.55;
    will-change: transform;
}
.lbs-1 { width: 320px; height: 320px; top: 8%;  left: 6%;  background: radial-gradient(circle at 30% 30%, #a5b4fc, transparent 70%); animation: lbsFloat1 26s ease-in-out infinite; }
.lbs-2 { width: 380px; height: 380px; top: 50%; left: 70%; background: radial-gradient(circle at 30% 30%, #93c5fd, transparent 70%); animation: lbsFloat2 32s ease-in-out infinite; }
.lbs-3 { width: 260px; height: 260px; top: 70%; left: 18%; background: radial-gradient(circle at 30% 30%, #f0abfc, transparent 70%); animation: lbsFloat3 29s ease-in-out infinite; }
.lbs-4 { width: 300px; height: 300px; top: 14%; left: 60%; background: radial-gradient(circle at 30% 30%, #99f6e4, transparent 70%); animation: lbsFloat1 35s ease-in-out infinite reverse; }
.lbs-5 { width: 220px; height: 220px; top: 38%; left: 36%; background: radial-gradient(circle at 30% 30%, #c4b5fd, transparent 70%); animation: lbsFloat2 24s ease-in-out infinite reverse; }
.lbs-6 { width: 200px; height: 200px; top: 84%; left: 82%; background: radial-gradient(circle at 30% 30%, #fbcfe8, transparent 70%); animation: lbsFloat3 30s ease-in-out infinite; }

@keyframes lbsFloat1 {
    0%,100% { transform: translate(0,0) scale(1); }
    33%     { transform: translate(60px,-40px) scale(1.12); }
    66%     { transform: translate(-30px,50px) scale(0.92); }
}
@keyframes lbsFloat2 {
    0%,100% { transform: translate(0,0) scale(1); }
    33%     { transform: translate(-70px,30px) scale(0.9); }
    66%     { transform: translate(40px,-60px) scale(1.15); }
}
@keyframes lbsFloat3 {
    0%,100% { transform: translate(0,0) scale(1); }
    50%     { transform: translate(50px,40px) scale(1.1); }
}
@media (prefers-reduced-motion: reduce) {
    .light-bg-shapes .lbs { animation: none !important; }
}

