/* ════════════════════════════════════════════════════════════
   MOBILE / HAMBURGER NAVIGATION
   ════════════════════════════════════════════════════════════ */
.nav-burger {
    display: none;
    position: relative;
    z-index: 1101;
    flex-direction: column;
    justify-content: center;
    gap: 5px;
    width: 44px; height: 44px;
    padding: 0 10px;
    border-radius: 12px;
    border: 1px solid var(--glass-border);
    background: rgba(255,255,255,0.05);
    cursor: pointer;
}
.nav-burger span {
    display: block; height: 2px; width: 100%;
    background: #fff; border-radius: 2px;
    transition: transform 0.3s var(--ease-out-back), opacity 0.2s ease;
}
.navbar.nav-open .nav-burger span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.navbar.nav-open .nav-burger span:nth-child(2) { opacity: 0; }
.navbar.nav-open .nav-burger span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }
body.light-theme .nav-burger { background: rgba(99,102,241,0.07); border-color: rgba(99,102,241,0.2); }
body.light-theme .nav-burger span { background: #1e1b4b; }

.nav-backdrop {
    position: fixed; inset: 0;
    background: rgba(0,0,0,0.5);
    backdrop-filter: blur(3px);
    opacity: 0; pointer-events: none;
    transition: opacity 0.3s ease;
    z-index: 990;
}
.nav-backdrop.show { opacity: 1; pointer-events: auto; }

@media (max-width: 1180px) {
    /* navbar → simple flex bar with burger on the right */
    .navbar {
        display: flex !important;
        align-items: center;
        justify-content: space-between;
        padding: 1rem 5%;
    }
    .logo-container { margin-right: auto; }
    .btn-account { order: 2; justify-self: auto !important; }
    .nav-burger { display: flex; order: 3; margin-left: 12px; }

    /* nav links → slide-down dropdown panel */
    .nav-links-container.glass {
        position: fixed;
        top: 74px; left: 4%; right: 4%;
        margin: 0 !important;
        flex-direction: column;
        gap: 4px;
        padding: 12px;
        border-radius: 18px;
        background: rgba(12,12,18,0.97);
        backdrop-filter: blur(20px);
        box-shadow: 0 22px 55px rgba(0,0,0,0.55);
        transform: translateY(-14px) scale(0.98);
        opacity: 0; pointer-events: none;
        transition: transform 0.3s var(--ease-out-back), opacity 0.25s ease;
        z-index: 1100;
        max-height: 78vh; overflow-y: auto;
    }
    .navbar.nav-open .nav-links-container.glass {
        transform: translateY(0) scale(1);
        opacity: 1; pointer-events: auto;
    }
    .nav-links-container .nav-btn {
        width: 100%;
        justify-content: flex-start;
        padding: 14px 18px;
        border-radius: 12px;
        font-size: 1rem;
    }
    .nav-links-container .nav-btn span { display: inline !important; }
    body.light-theme .nav-links-container.glass { background: rgba(244,244,255,0.98); }

    .btn-account span { display: none; }
    .content-wrapper { margin-top: 96px; padding: 0 4% 50px; }

    /* tighten big section headers */
