/* ════════════════════════════════════════════════════════════
   TOAST
   ════════════════════════════════════════════════════════════ */
.toast-host {
    position: fixed; left: 50%; bottom: 30px; transform: translateX(-50%);
    z-index: 6000; display: flex; flex-direction: column; gap: 10px;
    align-items: center; pointer-events: none;
}
.toast {
    display: inline-flex; align-items: center; gap: 11px;
    padding: 13px 20px; border-radius: 14px;
    background: rgba(17,18,30,0.92); border: 1px solid rgba(99,102,241,0.30);
    color: #e6e9ff; font-size: 0.9rem; font-weight: 600;
    box-shadow: 0 16px 44px rgba(5,6,20,0.55); backdrop-filter: blur(14px);
    opacity: 0; transform: translateY(16px) scale(0.97);
    transition: opacity 0.4s var(--ease-smooth), transform 0.45s var(--ease-out-back);
}
.toast.show { opacity: 1; transform: translateY(0) scale(1); }
.toast i { color: #818cf8; font-size: 1.05rem; }
body.light-theme .toast {
    background: rgba(255,255,255,0.96); border-color: rgba(99,102,241,0.25);
    color: #1e1b4b; box-shadow: 0 16px 44px rgba(99,102,241,0.18);
}

/* ═══════════════════════════════════════════════════════════
   LIGHTWEIGHT MODE  (applied via <html class="lite-mode">)
   Strips the GPU/CPU-heavy effects for weak devices so the page
   stays smooth and doesn't glitch.
   ═══════════════════════════════════════════════════════════ */
/* Kill the decorative background layers entirely */
html.lite-mode #particles-canvas,
html.lite-mode .bg-gradient-overlay,
html.lite-mode .vignette,
html.lite-mode .ambient-light,
html.lite-mode .light-bg-shapes {
    display: none !important;
}

/* Remove blur compositing and continuous animations everywhere */
html.lite-mode *,
html.lite-mode *::before,
html.lite-mode *::after {
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    animation: none !important;
    background-attachment: scroll !important;
    will-change: auto !important;
}

/* Keep functional loading spinners turning (cheap GPU transform) */
html.lite-mode .spin-loader {
    animation: spin 0.8s linear infinite !important;
}

/* Drop expensive blur() filters (glows, soft shadows via filter) */
html.lite-mode .af-card-glow,
html.lite-mode .lu-hero-bg,
html.lite-mode .hero-visual-block::before,
html.lite-mode .hero-visual-block::after {
    filter: none !important;
    opacity: 0.5 !important;
}

/* Glass panels lose their blur, so give them a readable solid fill */
html.lite-mode .glass,
html.lite-mode .glass-nav,
html.lite-mode .navbar {
    background: rgba(18, 18, 24, 0.95) !important;
}
html.lite-mode body.light-theme .glass,
html.lite-mode body.light-theme .glass-nav,
html.lite-mode body.light-theme .navbar {
    background: rgba(248, 249, 255, 0.97) !important;
}

/* Trim heavy transition work down to quick, cheap fades */
html.lite-mode .animate-on-scroll {
    transition: opacity 0.25s ease !important;
    transform: none !important;
}
html.lite-mode .animate-on-scroll.visible { transform: none !important; }

/* The 3D tilt/magnetic transforms are disabled in JS; neutralise any
   inline transform left behind */
html.lite-mode .tilt-card-lg,
html.lite-mode .tilt-card-sm,
html.lite-mode .magnetic-btn {
    transform: none !important;
}

/* ── Lightweight-mode warning banner ──────────────────────── */
.lite-banner {
    position: fixed;
    left: 50%;
    bottom: 20px;
    transform: translateX(-50%) translateY(140%);
    z-index: 1200;
    display: flex;
    align-items: center;
    gap: 12px;
    max-width: min(560px, calc(100vw - 32px));
    padding: 12px 16px;
    border-radius: 14px;
    background: rgba(18, 18, 24, 0.96);
    border: 1px solid rgba(245, 158, 11, 0.45);
    color: #f8fafc;
    font-size: 0.9rem;
    line-height: 1.35;
    box-shadow: 0 14px 40px rgba(0, 0, 0, 0.45);
    transition: transform 0.4s cubic-bezier(0.23, 1, 0.32, 1), opacity 0.3s ease;
    opacity: 0;
}
.lite-banner.show { transform: translateX(-50%) translateY(0); opacity: 1; }
.lite-banner .lite-banner-icon { color: #f59e0b; font-size: 1.15rem; flex-shrink: 0; }
.lite-banner .lite-banner-text { flex: 1; }
.lite-banner .lite-banner-text strong { color: #fbbf24; }
.lite-banner .lite-banner-actions { display: flex; align-items: center; gap: 6px; flex-shrink: 0; }
.lite-banner button {
    font-family: inherit;
    cursor: pointer;
    border-radius: 9px;
    border: 1px solid transparent;
    transition: background 0.2s ease, border-color 0.2s ease;
}
.lite-banner .lite-banner-full {
    padding: 7px 12px;
    background: linear-gradient(135deg, #f59e0b, #d97706);
    color: #1a1206;
    font-weight: 600;
    white-space: nowrap;
}
.lite-banner .lite-banner-full:hover { filter: brightness(1.08); }
.lite-banner .lite-banner-close {
    width: 30px; height: 30px;
    display: flex; align-items: center; justify-content: center;
    background: transparent;
    color: #9ca3af;
    border-color: rgba(255, 255, 255, 0.12);
}
.lite-banner .lite-banner-close:hover { background: rgba(255, 255, 255, 0.08); color: #fff; }
body.light-theme .lite-banner {
    background: rgba(255, 255, 255, 0.98);
    color: #1e1b4b;
    box-shadow: 0 14px 40px rgba(99, 102, 241, 0.18);
}
body.light-theme .lite-banner .lite-banner-close { color: #6b7280; border-color: rgba(0,0,0,0.12); }

/* ── Lightweight-mode toggle FAB ──────────────────────────── */
.lite-fab {
    position: fixed;
    bottom: 154px;
    right: 30px;
    width: 50px; height: 50px;
    border-radius: 50%;
    background: rgba(99,102,241,0.18);
    border: 1px solid rgba(99,102,241,0.35);
    color: #a5b4fc;
    cursor: pointer;
    display: flex; align-items: center; justify-content: center;
    font-size: 1.1rem;
    z-index: 998;
    box-shadow: 0 4px 20px rgba(99,102,241,0.25);
    transition: transform 0.35s var(--ease-out-back), background 0.25s ease, box-shadow 0.25s ease, color 0.25s ease;
}
.lite-fab:hover {
    background: rgba(99,102,241,0.3);
    transform: scale(1.12);
    box-shadow: 0 6px 28px rgba(99,102,241,0.4);
}
/* When lite mode is active, light up the FAB so its state is obvious */
html.lite-mode .lite-fab {
    background: rgba(245, 158, 11, 0.22);
    border-color: rgba(245, 158, 11, 0.5);
    color: #fbbf24;
    box-shadow: 0 4px 20px rgba(245, 158, 11, 0.28);
}
body.light-theme .lite-fab { background: rgba(99,102,241,0.12); border-color: rgba(99,102,241,0.28); color: #6366f1; box-shadow: 0 4px 18px rgba(99,102,241,0.15); }
html.lite-mode body.light-theme .lite-fab { background: rgba(245,158,11,0.16); border-color: rgba(245,158,11,0.4); color: #b45309; }

@media (max-width: 768px) {
    .lite-fab { width: 44px; height: 44px; bottom: 134px; right: 16px; font-size: 1rem; }
