/* ==========================================================
   Spectral atmosphere v3 — calmer motion, stronger identity
   ========================================================== */
:root {
    --pointer-x: 52vw;
    --pointer-y: 34vh;
    --motion-fluid: cubic-bezier(.22, 1, .36, 1);
}

body::before {
    content: "";
    position: fixed;
    inset: 0;
    z-index: 0;
    pointer-events: none;
    background: radial-gradient(420px circle at var(--pointer-x) var(--pointer-y), rgba(121, 139, 255, .085), transparent 70%);
    transition: opacity .6s ease;
}

.spectral-backdrop {
    position: fixed;
    top: clamp(90px, 14vh, 160px);
    right: clamp(-280px, -11vw, -100px);
    width: min(70vw, 1050px);
    aspect-ratio: 1.35;
    z-index: 0;
    pointer-events: none;
    opacity: .66;
    transform: translate3d(0, 0, 0);
    contain: layout paint;
    mask-image: radial-gradient(ellipse at 58% 45%, #000 12%, rgba(0,0,0,.9) 50%, transparent 78%);
}

.spectral-horizon {
    position: absolute;
    left: -12%;
    right: 0;
    bottom: 8%;
    height: 44%;
    background-image:
        linear-gradient(rgba(116, 132, 236, .085) 1px, transparent 1px),
        linear-gradient(90deg, rgba(116, 132, 236, .085) 1px, transparent 1px);
    background-size: 54px 34px;
    transform: perspective(520px) rotateX(68deg) scaleX(1.22);
    transform-origin: 50% 100%;
    mask-image: linear-gradient(to top, #000, transparent 88%);
    animation: spectralHorizonFlow 16s linear infinite;
}

.spectral-core {
    position: absolute;
    left: 55%;
    top: 44%;
    width: clamp(280px, 34vw, 510px);
    aspect-ratio: 1;
    transform: translate(-50%, -50%);
    animation: spectralCoreFloat 10s var(--motion-fluid) infinite alternate;
}

.spectral-core-glow {
    position: absolute;
    inset: 18%;
    border-radius: 50%;
    background: conic-gradient(from 210deg, rgba(94, 106, 255, .16), rgba(43, 198, 255, .2), rgba(231, 81, 214, .17), rgba(94, 106, 255, .16));
    filter: blur(38px);
    animation: spectralGlowPulse 7s ease-in-out infinite;
}

.spectral-ring {
    position: absolute;
    left: 50%;
    top: 50%;
    border: 1px solid rgba(144, 157, 255, .2);
    border-radius: 50%;
    box-shadow: inset 0 0 30px rgba(76, 94, 220, .035), 0 0 30px rgba(76, 94, 220, .04);
}

.spectral-ring::before,
.spectral-ring::after {
    content: "";
    position: absolute;
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background: #b9c4ff;
    box-shadow: 0 0 16px 5px rgba(115, 135, 255, .5);
}

.spectral-ring-a { inset: 8%; transform: rotate(-13deg); animation: spectralRingA 24s linear infinite; }
.spectral-ring-a::before { left: 13%; top: 16%; }
.spectral-ring-a::after { right: 9%; bottom: 23%; width: 4px; height: 4px; }
.spectral-ring-b { inset: 20% 4%; transform: rotate(42deg); border-color: rgba(89, 195, 245, .16); animation: spectralRingB 31s linear infinite reverse; }
.spectral-ring-b::before { right: 20%; top: 6%; background: #8de2ff; }
.spectral-ring-b::after { left: 7%; bottom: 31%; width: 4px; height: 4px; }
.spectral-ring-c { inset: 31% 14%; transform: rotate(-35deg); border-color: rgba(226, 104, 220, .14); animation: spectralRingA 19s linear infinite reverse; }
.spectral-ring-c::before { left: 45%; bottom: -4px; background: #f2a9ed; }
.spectral-ring-c::after { display: none; }

.spectral-prism {
    position: absolute;
    left: 50%;
    top: 50%;
    width: 18%;
    aspect-ratio: 1;
    transform: translate(-50%, -50%) rotate(45deg);
    border-radius: 22%;
    border: 1px solid rgba(218, 224, 255, .42);
    background:
        linear-gradient(135deg, rgba(255,255,255,.2), transparent 34%),
        linear-gradient(315deg, rgba(101,114,255,.22), rgba(30,39,105,.08));
    box-shadow: 0 0 38px rgba(105, 121, 255, .24), inset 0 0 28px rgba(220, 227, 255, .08);
    backdrop-filter: blur(3px);
    animation: spectralPrismTurn 13s ease-in-out infinite alternate;
}

.spectral-ray {
    position: absolute;
    left: 54%;
    top: 44%;
    width: 64%;
    height: 1px;
    transform-origin: 0 50%;
    opacity: .58;
    filter: drop-shadow(0 0 8px currentColor);
}

.spectral-ray::after {
    content: "";
    position: absolute;
    inset: -7px 0;
    background: linear-gradient(90deg, currentColor, transparent 78%);
    opacity: .08;
    clip-path: polygon(0 48%, 100% 0, 100% 100%, 0 52%);
}

.spectral-ray-a { color: #7887ff; background: linear-gradient(90deg, currentColor, transparent); transform: rotate(-18deg); animation: spectralRayBreath 5.2s ease-in-out infinite; }
.spectral-ray-b { color: #5dd9ff; background: linear-gradient(90deg, currentColor, transparent); transform: rotate(4deg); animation: spectralRayBreath 6.4s ease-in-out .8s infinite; }
.spectral-ray-c { color: #e47ad7; background: linear-gradient(90deg, currentColor, transparent); transform: rotate(24deg); animation: spectralRayBreath 7.1s ease-in-out 1.7s infinite; }

.spectral-label {
    position: absolute;
    right: 13%;
    bottom: 15%;
    display: flex;
    gap: 12px;
    align-items: center;
    font-size: .54rem;
    letter-spacing: .18em;
    color: rgba(187, 196, 237, .38);
}
.spectral-label span { padding-right: 12px; border-right: 1px solid rgba(155, 166, 224, .16); }
.spectral-label b { color: rgba(112, 223, 183, .54); font-weight: 700; }

.content-wrapper { position: relative; z-index: 1; }
.theme-fab,
.lite-fab,
.scroll-to-top { z-index: 1100; }

.navbar {
    transition: transform .55s var(--motion-fluid), background .35s ease, box-shadow .35s ease, padding .35s ease;
}

.nav-links-container.glass {
    box-shadow: 0 18px 55px rgba(0,0,0,.28), inset 0 1px rgba(255,255,255,.035);
}

.nav-btn {
    transition: color .3s ease, background .4s var(--motion-fluid), transform .45s var(--motion-fluid), box-shadow .4s ease, border-color .35s ease;
}

.nav-btn::before {
    left: 12%;
    top: auto;
    bottom: 4px;
    width: 76%;
    height: 2px;
    border-radius: 99px;
    background: linear-gradient(90deg, transparent, #7887ff, #6ee7ff, transparent);
    opacity: 0;
    transform: scaleX(.25);
    transition: opacity .3s ease, transform .45s var(--motion-fluid);
}
.nav-btn:hover::before,
.nav-btn.active::before { left: 12%; opacity: .9; transform: scaleX(1); }

.tab-content {
    transform: translateY(14px) scale(.992);
    transition: opacity .4s ease, transform .58s var(--motion-fluid);
    transform-origin: 50% 60px;
}

.animate-on-scroll {
    transform: translateY(22px) scale(.992);
    transition: opacity .65s ease, transform .9s var(--motion-fluid);
}

.hero-text-block h1 {
    letter-spacing: -.045em;
    text-wrap: balance;
    text-shadow: 0 14px 50px rgba(0,0,0,.3);
}

.hero-text-block p { text-wrap: pretty; }

.status-badge {
    box-shadow: inset 0 1px rgba(255,255,255,.08), 0 12px 32px rgba(0,0,0,.18);
}

.feature-card,
.timeline-card,
.account-card,
.support-card,
.af-card {
    transition-timing-function: var(--motion-fluid) !important;
}

.feature-card {
    isolation: isolate;
    box-shadow: 0 22px 55px rgba(2,5,20,.2), inset 0 1px rgba(255,255,255,.035);
}

.feature-card::after {
    content: "";
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: inherit;
    background: radial-gradient(300px circle at 20% 0%, rgba(112,127,255,.1), transparent 58%);
    opacity: 0;
    transition: opacity .45s ease;
}
.feature-card:hover::after { opacity: 1; }

body.light-theme::before {
    background: radial-gradient(440px circle at var(--pointer-x) var(--pointer-y), rgba(84, 104, 214, .075), transparent 72%);
}
body.light-theme .spectral-backdrop { opacity: .4; }
body.light-theme .spectral-ring { border-color: rgba(67, 85, 177, .18); }
body.light-theme .spectral-prism { border-color: rgba(75, 91, 183, .28); background: linear-gradient(135deg, rgba(255,255,255,.78), rgba(107,124,224,.1)); box-shadow: 0 0 42px rgba(88,105,205,.15), inset 0 0 24px rgba(255,255,255,.5); }
body.light-theme .spectral-horizon { opacity: .55; }
body.light-theme .spectral-label { color: rgba(54, 65, 126, .38); }

html.lite-mode body::before,
html.lite-mode .spectral-backdrop { display: none !important; }

@keyframes spectralHorizonFlow { to { background-position: 108px 68px, 108px 68px; } }
@keyframes spectralCoreFloat { to { transform: translate(-50%, -53%) rotate(1.2deg); } }
@keyframes spectralGlowPulse { 50% { opacity: .66; transform: scale(1.12); } }
@keyframes spectralRingA { to { transform: rotate(347deg); } }
@keyframes spectralRingB { to { transform: rotate(402deg); } }
@keyframes spectralPrismTurn { to { transform: translate(-50%, -50%) rotate(51deg) scale(1.04); } }
@keyframes spectralRayBreath { 0%,100% { opacity: .24; } 50% { opacity: .72; } }

@media (max-width: 1100px) {
    .spectral-backdrop { right: -28vw; width: 92vw; opacity: .48; }
    .spectral-label { display: none; }
}

@media (max-width: 760px) {
    .spectral-backdrop { top: 110px; right: -58vw; width: 145vw; opacity: .32; }
    body::before { opacity: .55; }
    .nav-btn::before { display: none; }
    .hero-text-block h1 { letter-spacing: -.035em; }
}

@media (prefers-reduced-motion: reduce) {
    .spectral-backdrop *, .spectral-backdrop { animation: none !important; }
    .navbar, .nav-btn, .tab-content, .animate-on-scroll { transition-duration: .01ms !important; }
}

/* ================================================================
   LIGHT THEME 2.0 — UPDATES, DEVELOPMENT, FEATURES, SUPPORT, PROFILE
   Opaque daylight surfaces, stronger contrast and lighter paint work.
   ================================================================ */
body.light-theme {
    --day-ink: #202747;
    --day-heading: #171d3f;
    --day-copy: #5f698d;
    --day-muted: #7b85a6;
    --day-line: rgba(68, 79, 145, .14);
    --day-line-strong: rgba(79, 70, 229, .24);
    --day-surface: rgba(255, 255, 255, .92);
    --day-surface-soft: rgba(246, 248, 255, .90);
    --day-shadow: 0 22px 58px rgba(65, 75, 132, .12), inset 0 1px #fff;
}

body.light-theme :is(#updates, #development, #advanced-features, #support) {
    color: var(--day-ink);
}

body.light-theme :is(#updates, #development, #advanced-features, #support) :is(h2, h3, h4, strong) {
    text-shadow: none;
}

/* Updates */
body.light-theme #updates .updates-header {
    border-color: var(--day-line-strong);
    background:
        radial-gradient(620px circle at 4% 0%, rgba(112, 96, 255, .17), transparent 64%),
        radial-gradient(460px circle at 98% 100%, rgba(49, 190, 220, .11), transparent 68%),
        linear-gradient(145deg, #fff, #f1f4ff) !important;
    box-shadow: var(--day-shadow) !important;
}

