/* Navigation and release hub polish. */

/* The active state stays a capsule; no decorative underline. */
.nav-btn::before { display: none !important; }
.nav-btn.active {
    border-color: rgba(154, 164, 255, .18);
    background: linear-gradient(135deg, rgba(255,255,255,.15), rgba(116,126,218,.09));
    box-shadow: inset 0 1px rgba(255,255,255,.1), 0 7px 22px rgba(4,6,24,.24);
}
body.light-theme .nav-btn.active {
    background: linear-gradient(135deg, rgba(255,255,255,.92), rgba(230,234,255,.88));
    border-color: rgba(91, 105, 190, .2);
}

/* Updates hero */
#updates { max-width: 1180px; margin: 0 auto; }
.updates-header {
    position: relative;
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 28px;
    padding: 40px 42px 34px;
    margin: 0 0 22px;
    text-align: left;
    border: 1px solid rgba(255,255,255,.075);
    border-radius: 28px;
    overflow: hidden;
    background:
        radial-gradient(650px circle at 8% -20%, rgba(99,102,241,.24), transparent 58%),
        radial-gradient(460px circle at 100% 110%, rgba(41,174,220,.12), transparent 58%),
        linear-gradient(145deg, rgba(20,23,48,.88), rgba(10,13,29,.9));
    box-shadow: 0 30px 90px rgba(1,3,16,.28), inset 0 1px rgba(255,255,255,.05);
}
.updates-header::before {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(110deg, transparent 10%, rgba(255,255,255,.035) 42%, transparent 62%);
    transform: translateX(-100%);
    animation: updatesHeaderSweep 9s ease-in-out infinite;
    pointer-events: none;
}
.updates-heading-copy { position: relative; z-index: 1; }
.updates-eyebrow {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 12px;
    color: #aeb8ef;
    font-size: .68rem;
    font-weight: 800;
    letter-spacing: .16em;
    text-transform: uppercase;
}
.updates-eyebrow i { color: #7d8cff; animation: updatesSignal 2.4s ease-in-out infinite; }
.updates-header h2 { font-size: clamp(2.35rem, 5vw, 4rem); line-height: 1; letter-spacing: -.045em; }
.updates-header p { margin-top: 13px; max-width: 650px; color: var(--text-muted); font-size: 1rem; }
.updates-header .dev-write-btn {
    position: relative;
    z-index: 2;
    align-self: start;
    padding: 12px 18px;
    border: 1px solid rgba(140,151,255,.28);
    border-radius: 14px;
    background: rgba(104,113,237,.13);
    color: #dce1ff;
    font: 700 .85rem 'Onest', sans-serif;
    gap: 8px;
    cursor: pointer;
    box-shadow: inset 0 1px rgba(255,255,255,.08);
    transition: transform .4s var(--motion-fluid), background .3s ease, box-shadow .3s ease;
}
.updates-header .dev-write-btn:hover { transform: translateY(-2px); background: rgba(104,113,237,.23); box-shadow: 0 12px 28px rgba(70,74,200,.22); }
.updates-overview {
    position: relative;
    z-index: 1;
    grid-column: 1 / -1;
    display: flex;
    gap: 10px;
    margin-top: 10px;
}
.updates-overview div {
    min-width: 116px;
    padding: 12px 16px;
    border: 1px solid rgba(255,255,255,.065);
    border-radius: 14px;
    background: rgba(5,8,24,.28);
    backdrop-filter: blur(8px);
}
.updates-overview strong { display: block; color: #eef1ff; font-size: 1rem; line-height: 1.2; }
.updates-overview span { display: block; margin-top: 3px; color: #7f89b0; font-size: .66rem; text-transform: uppercase; letter-spacing: .08em; }

/* Search, filters and sorting */
.updates-toolbar {
    position: sticky;
    top: 14px;
    z-index: 40;
    display: grid;
    grid-template-columns: minmax(230px, 1fr) auto auto;
    align-items: center;
    gap: 10px;
    padding: 10px;
    margin: 0 0 28px;
    border: 1px solid rgba(255,255,255,.08);
    border-radius: 18px;
    background: rgba(8,10,24,.78);
    backdrop-filter: blur(22px) saturate(1.25);
    box-shadow: 0 18px 48px rgba(0,0,0,.22);
}
.updates-search {
    display: flex;
    align-items: center;
    gap: 9px;
    min-width: 0;
    padding: 0 12px;
    height: 42px;
    border-radius: 12px;
    color: #7d86aa;
    background: rgba(255,255,255,.035);
    border: 1px solid transparent;
    transition: border-color .25s ease, background .25s ease;
}
.updates-search:focus-within { border-color: rgba(111,124,255,.36); background: rgba(101,111,228,.07); }
.updates-search input { min-width: 0; flex: 1; border: 0; outline: 0; background: transparent; color: var(--text); font: 500 .86rem 'Onest', sans-serif; }
.updates-search input::placeholder { color: #697291; }
.updates-search kbd { padding: 3px 6px; border: 1px solid rgba(255,255,255,.08); border-radius: 6px; color: #737c9f; font: 600 .58rem 'Onest', sans-serif; background: rgba(255,255,255,.035); }
.updates-filters { display: flex; gap: 5px; }
.updates-filter {
    height: 38px;
    padding: 0 11px;
    border: 1px solid transparent;
    border-radius: 10px;
    background: transparent;
    color: #8d95b3;
    font: 650 .72rem 'Onest', sans-serif;
    cursor: pointer;
    transition: color .25s ease, background .3s ease, transform .35s var(--motion-fluid), border-color .25s ease;
}
.updates-filter i { margin-right: 4px; font-size: .65rem; }
.updates-filter:hover { color: #dbe0fa; background: rgba(255,255,255,.055); transform: translateY(-1px); }
.updates-filter.active { color: #f0f2ff; background: rgba(105,115,235,.16); border-color: rgba(122,133,255,.2); }
.updates-sort {
    height: 38px;
    padding: 0 30px 0 11px;
    border: 1px solid rgba(255,255,255,.07);
    border-radius: 10px;
    outline: 0;
    background: rgba(255,255,255,.04);
    color: #aab1ce;
    font: 600 .72rem 'Onest', sans-serif;
    cursor: pointer;
}
.updates-sort option { background: #111528; }

/* Interactive release cards */
.updates-timeline { max-width: 1040px; margin: 12px auto 0; padding: 18px 0 48px; }
.timeline-line {
    left: 28px;
    width: 2px;
    transform: none;
    overflow: hidden;
    background: linear-gradient(to bottom, rgba(99,102,241,.05), rgba(99,102,241,.38) 12%, rgba(64,184,220,.28) 80%, rgba(99,102,241,.02));
}
.timeline-line::after {
    content: "";
    position: absolute;
    inset: -35% 0 70%;
    background: linear-gradient(to bottom, transparent, #aeb8ff, transparent);
    animation: timelineBeam 4.8s ease-in-out infinite;
}
.timeline-item {
    display: block;
    margin: 0 0 24px;
    padding-left: 76px;
    opacity: 0;
    transform: translateY(22px);
    transition: opacity .55s ease, transform .75s var(--motion-fluid);
}
.timeline-item.in-view { opacity: 1; transform: translateY(0); }
.date-badge {
    left: 0;
    top: 25px;
    width: 58px;
    padding: 6px 4px;
    transform: none;
    text-align: center;
    border-radius: 10px;
    color: #9da6c9;
    background: #0a0d1d;
    font-size: .61rem;
    line-height: 1.2;
    box-shadow: 0 0 0 6px rgba(7,9,20,.8);
}
.timeline-item:hover .date-badge { transform: scale(1.04); background: #5966d8; }
.timeline-card {
    width: 100%;
    padding: 0;
    border-radius: 22px;
    overflow: hidden;
    background: linear-gradient(155deg, rgba(21,24,47,.9), rgba(10,13,29,.92));
    border-color: rgba(255,255,255,.075);
    box-shadow: 0 18px 50px rgba(0,0,0,.18), inset 0 1px rgba(255,255,255,.035);
    transform: none !important;
}
.timeline-card::before { display: none; }
.timeline-card::after {
    content: "";
    position: absolute;
    inset: 0;
    pointer-events: none;
    background: radial-gradient(420px circle at var(--card-x, 50%) var(--card-y, 0%), rgba(114,126,255,.12), transparent 65%);
    opacity: 0;
    transition: opacity .35s ease;
}
.timeline-card:hover { transform: none; border-color: rgba(119,130,244,.25); box-shadow: 0 24px 65px rgba(0,0,0,.28), 0 0 0 1px rgba(108,119,239,.08); }
.timeline-card:hover::after { opacity: 1; }
.timeline-card.is-current { border-color: rgba(115,126,245,.34); box-shadow: 0 22px 70px rgba(41,43,132,.22), inset 0 1px rgba(255,255,255,.045); }
.timeline-card.is-current::before { display: block; height: 2px; }
.release-card-head { position: relative; z-index: 1; display: flex; gap: 18px; align-items: flex-start; padding: 24px 26px 18px; }
.release-icon {
    width: 44px;
    height: 44px;
    flex: 0 0 44px;
    display: grid;
    place-items: center;
    border: 1px solid rgba(132,144,255,.2);
    border-radius: 13px;
    color: #aeb8ff;
    background: linear-gradient(145deg, rgba(106,117,235,.18), rgba(38,46,106,.12));
    box-shadow: inset 0 1px rgba(255,255,255,.06);
}
.release-card-main { min-width: 0; flex: 1; }
.release-meta { display: flex; flex-wrap: wrap; align-items: center; gap: 7px; margin-bottom: 7px; }
.release-version, .release-channel, .release-change-count { padding: 3px 8px; border-radius: 7px; font-size: .61rem; font-weight: 750; letter-spacing: .045em; text-transform: uppercase; }
.release-version { color: #b7c0ff; background: rgba(103,114,234,.13); border: 1px solid rgba(117,128,245,.15); }
.release-channel { color: #7fd6ba; background: rgba(30,173,126,.09); }
.release-channel.beta { color: #f0bf73; background: rgba(217,145,39,.1); }
.release-channel.dev { color: #d493f0; background: rgba(184,75,222,.1); }
.release-channel.website { color: #77c7ea; background: rgba(46,159,208,.1); }
.release-change-count { color: #818aa9; background: rgba(255,255,255,.035); }
.release-card-main h3 { font-size: 1.23rem; line-height: 1.25; color: #f1f3ff; }
.release-summary { max-width: 760px; margin-top: 7px; color: #929bbd; font-size: .82rem; line-height: 1.55; }
.release-actions { position: relative; z-index: 3; display: flex; gap: 5px; }
.release-action {
    width: 34px;
    height: 34px;
    display: grid;
    place-items: center;
    border: 1px solid rgba(255,255,255,.07);
    border-radius: 10px;
    color: #7781a5;
    background: rgba(255,255,255,.025);
    cursor: pointer;
    transition: color .25s ease, background .25s ease, transform .35s var(--motion-fluid);
}
.release-action:hover { color: #dfe4ff; background: rgba(110,120,237,.12); transform: translateY(-2px); }
.release-action.danger:hover { color: #ff9898; background: rgba(239,68,68,.1); }
.release-details { position: relative; z-index: 1; display: grid; grid-template-rows: 0fr; transition: grid-template-rows .6s var(--motion-fluid); }
.timeline-card.expanded .release-details { grid-template-rows: 1fr; }
.release-details-inner { min-height: 0; overflow: hidden; }
.release-details-content { padding: 0 26px 4px 88px; }
.release-details .changelog { padding: 4px 0 8px; }
.release-details .changelog li { opacity: 0; transform: translateX(-8px); transition: opacity .35s ease, transform .45s var(--motion-fluid); }
.timeline-card.expanded .release-details .changelog li { opacity: 1; transform: translateX(0); }
.timeline-card.expanded .release-details .changelog li:nth-child(2) { transition-delay: .04s; }
.timeline-card.expanded .release-details .changelog li:nth-child(3) { transition-delay: .08s; }
.timeline-card.expanded .release-details .changelog li:nth-child(4) { transition-delay: .12s; }
.timeline-card.expanded .release-details .changelog li:nth-child(n+5) { transition-delay: .16s; }
.changelog li.breaking::before { content: '\f071'; color: #fb7185; background: rgba(244,63,94,.13); }
.changelog li.security::before { content: '\f3ed'; color: #c084fc; background: rgba(168,85,247,.13); }
.changelog li strong { color: #eef0ff; font-weight: 700; }
.changelog li code { padding: 2px 6px; border: 1px solid rgba(138,149,240,.15); border-radius: 6px; color: #bfc7ff; background: rgba(99,102,241,.09); font: 600 .79rem Consolas, monospace; }
.changelog li a { color: #8fcff2; text-decoration: none; border-bottom: 1px dashed rgba(143,207,242,.35); }
.release-card-foot { position: relative; z-index: 2; display: flex; justify-content: space-between; align-items: center; padding: 12px 26px 14px 88px; border-top: 1px solid rgba(255,255,255,.05); }
.release-type-summary { display: flex; gap: 12px; color: #6f799d; font-size: .66rem; }
.release-type-summary span { display: inline-flex; align-items: center; gap: 5px; }
.release-type-summary i.add { color: #35c992; }.release-type-summary i.imp { color: #65a6ff; }.release-type-summary i.fix { color: #efb14e; }
.release-expand {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 7px 10px;
    border: 0;
    border-radius: 9px;
    color: #9ca5c8;
    background: transparent;
    font: 650 .7rem 'Onest', sans-serif;
    cursor: pointer;
    transition: color .25s ease, background .25s ease;
}
.release-expand:hover { color: #e0e4ff; background: rgba(255,255,255,.045); }
.release-expand i { transition: transform .45s var(--motion-fluid); }
.timeline-card.expanded .release-expand i { transform: rotate(180deg); }
.updates-empty { padding: 80px 20px; text-align: center; color: #7f89aa; }
.updates-empty > i { font-size: 2rem; color: #6874da; margin-bottom: 14px; }
.updates-empty h3 { color: #dce1f6; margin-bottom: 6px; }
.updates-empty button { margin-top: 18px; padding: 9px 15px; border: 1px solid rgba(119,130,244,.2); border-radius: 10px; background: rgba(105,115,235,.1); color: #bfc6f4; cursor: pointer; }

/* Rich local update editor */
.news-editor-modal { width: min(1180px, 96vw); max-width: none; max-height: 94vh; padding: 0; overflow: hidden; }
.news-editor-modal .close-dashboard { z-index: 5; top: 18px; right: 18px; }
.news-editor-heading { display: flex; align-items: center; gap: 14px; padding: 22px 28px; border-bottom: 1px solid rgba(255,255,255,.065); background: rgba(255,255,255,.018); }
.news-editor-icon { width: 43px; height: 43px; display: grid; place-items: center; border-radius: 13px; color: #b8c1ff; background: rgba(106,117,235,.14); border: 1px solid rgba(125,136,248,.18); }
.news-editor-heading > div > span { color: #7d88b3; font-size: .61rem; text-transform: uppercase; letter-spacing: .13em; font-weight: 800; }
.news-editor-heading h2 { font-size: 1.35rem; line-height: 1.15; }
.news-editor-heading p { margin-top: 3px; color: var(--text-muted); font-size: .75rem; }
.news-editor-layout { display: grid; grid-template-columns: minmax(0, 1.35fr) minmax(320px, .75fr); min-height: 0; max-height: calc(94vh - 88px); }
.news-editor-fields { padding: 24px 26px 28px; overflow-y: auto; }
.news-field-grid { display: grid; grid-template-columns: minmax(0, 1.55fr) minmax(120px, .55fr); gap: 14px; }
.news-field { display: flex; flex-direction: column; gap: 6px; margin-bottom: 14px; color: #929bbb; font-size: .69rem; font-weight: 700; letter-spacing: .025em; }
.news-field input, .news-field select, .news-field textarea {
    width: 100%;
    padding: 11px 12px;
    border: 1px solid rgba(255,255,255,.085);
    border-radius: 11px;
    outline: 0;
    resize: vertical;
    background: rgba(255,255,255,.035);
    color: #edf0ff;
    font: 500 .85rem 'Onest', sans-serif;
    transition: border-color .25s ease, background .25s ease, box-shadow .25s ease;
}
.news-field input:focus, .news-field select:focus, .news-field textarea:focus { border-color: rgba(111,124,255,.45); background: rgba(104,114,232,.06); box-shadow: 0 0 0 3px rgba(99,102,241,.07); }
.news-field select option { background: #13172b; }
.news-current-toggle { display: grid; grid-template-columns: 38px 1fr; grid-template-rows: auto auto; column-gap: 10px; align-items: center; padding: 11px 12px; margin-bottom: 18px; border: 1px solid rgba(255,255,255,.07); border-radius: 12px; background: rgba(255,255,255,.025); cursor: pointer; }
.news-current-toggle input { position: absolute; opacity: 0; pointer-events: none; }
.news-current-toggle > span { grid-row: 1 / 3; width: 38px; height: 38px; display: grid; place-items: center; border-radius: 10px; color: #747d9d; background: rgba(255,255,255,.04); transition: color .25s, background .25s, transform .35s var(--motion-fluid); }
.news-current-toggle input:checked + span { color: #bdc5ff; background: rgba(103,114,234,.16); transform: rotate(-5deg); }
.news-current-toggle b { color: #d9ddf2; font-size: .78rem; }
.news-current-toggle small { color: #737d9e; font-size: .66rem; }
.news-items-editor { margin: 0; }
.nie-editor-head { display: flex; justify-content: space-between; gap: 12px; align-items: flex-start; margin-bottom: 10px; }
.nie-editor-head > div { display: flex; flex-direction: column; }
.nie-editor-head > div > span { color: #dbe0f5; font-size: .82rem; font-weight: 750; }
.nie-editor-head small { color: #747e9e; font-size: .64rem; margin-top: 2px; }
.nie-editor-head > span { padding: 4px 8px; border-radius: 7px; color: #8993b8; background: rgba(255,255,255,.04); font-size: .62rem; }
.nie-quick-add { display: flex; flex-wrap: wrap; gap: 5px; margin-bottom: 10px; }
.nie-quick-add button, .news-editor-actions-secondary button {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 7px 9px;
    border: 1px solid rgba(255,255,255,.07);
    border-radius: 8px;
    color: #8f98b9;
    background: rgba(255,255,255,.025);
    font: 650 .66rem 'Onest', sans-serif;
    cursor: pointer;
    transition: color .2s ease, background .2s ease, transform .3s var(--motion-fluid);
}
.nie-quick-add button:hover, .news-editor-actions-secondary button:hover { color: #dce1f8; background: rgba(104,115,232,.09); transform: translateY(-1px); }
.news-item-row { position: relative; display: block; padding: 10px; margin-bottom: 8px; border: 1px solid rgba(255,255,255,.065); border-radius: 12px; background: rgba(255,255,255,.022); animation: newsRowIn .4s var(--motion-fluid) both; }
.nie-row-main { display: grid; grid-template-columns: 112px minmax(0, 1fr) auto; gap: 8px; align-items: start; }
.nie-type { width: 112px; height: 39px; padding: 0 9px; }
.nie-text { min-height: 52px; line-height: 1.45; resize: vertical; }
.nie-row-actions { display: grid; grid-template-columns: repeat(3, 28px); gap: 4px; }
.nie-row-actions button { width: 28px; height: 28px; display: grid; place-items: center; border: 0; border-radius: 7px; color: #7680a1; background: rgba(255,255,255,.035); cursor: pointer; }
.nie-row-actions button:hover { color: #dce0f4; background: rgba(104,114,232,.1); }
.nie-row-actions .nie-remove:hover { color: #fb8d8d; background: rgba(239,68,68,.1); }
.nie-format-bar { display: flex; gap: 4px; padding: 7px 0 0 120px; }
.nie-format-bar button { min-width: 27px; height: 25px; padding: 0 7px; border: 1px solid rgba(255,255,255,.055); border-radius: 6px; color: #7d87a8; background: rgba(255,255,255,.02); font: 650 .62rem 'Onest', sans-serif; cursor: pointer; }
.nie-format-bar button:hover { color: #cdd3f1; background: rgba(255,255,255,.05); }
.news-editor-actions-secondary { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 14px; }
.news-editor-actions-secondary button.danger { margin-left: auto; color: #b97d86; }
.news-publish-row { display: flex; justify-content: space-between; align-items: center; gap: 16px; padding-top: 18px; margin-top: 18px; border-top: 1px solid rgba(255,255,255,.055); }
.news-publish-row > span { color: #687398; font-size: .68rem; }
.news-publish-row > span i { margin-right: 5px; color: #45b987; }
.news-publish-row .btn-submit-login { width: auto; min-width: 174px; margin: 0; padding: 11px 18px; display: inline-flex; justify-content: center; gap: 10px; }
.news-preview-pane { padding: 20px; overflow-y: auto; border-left: 1px solid rgba(255,255,255,.065); background: linear-gradient(145deg, rgba(9,12,28,.75), rgba(16,20,42,.55)); }
.news-preview-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 16px; color: #8d97b8; font-size: .68rem; font-weight: 750; text-transform: uppercase; letter-spacing: .08em; }
.news-preview-head b { padding: 4px 7px; border-radius: 6px; color: #7180d8; background: rgba(99,102,241,.1); font-size: .56rem; }
.news-live-preview .timeline-card { width: 100%; }
.news-live-preview .release-card-head { padding: 20px 18px 14px; gap: 12px; }
.news-live-preview .release-icon { width: 38px; height: 38px; flex-basis: 38px; }
.news-live-preview .release-card-main h3 { font-size: 1.03rem; }
.news-live-preview .release-details { grid-template-rows: 1fr; }
.news-live-preview .release-details-content { padding: 0 18px 6px; }
.news-live-preview .release-details .changelog li { opacity: 1; transform: none; padding-left: 27px; font-size: .78rem; }
.news-preview-placeholder { display: grid; place-items: center; min-height: 320px; padding: 28px; border: 1px dashed rgba(255,255,255,.08); border-radius: 18px; color: #657093; text-align: center; }
.news-preview-placeholder i { display: block; margin-bottom: 10px; font-size: 1.5rem; color: #6976d4; }

body.light-theme .updates-header { border-color: rgba(73,88,164,.12); background: radial-gradient(600px circle at 8% -20%, rgba(99,102,241,.14), transparent 58%), linear-gradient(145deg, rgba(255,255,255,.86), rgba(237,241,255,.88)); box-shadow: 0 28px 70px rgba(70,82,145,.14); }
body.light-theme .updates-overview div, body.light-theme .updates-toolbar { background: rgba(255,255,255,.72); border-color: rgba(75,89,164,.12); }
body.light-theme .updates-overview strong, body.light-theme .release-card-main h3 { color: #27315d; }
body.light-theme .updates-toolbar { box-shadow: 0 16px 38px rgba(73,84,147,.12); }
body.light-theme .updates-search input { color: #28315d; }
body.light-theme .updates-filter.active { color: #4352b8; background: rgba(88,104,212,.1); }
body.light-theme .timeline-card { background: linear-gradient(155deg, rgba(255,255,255,.9), rgba(240,244,255,.92)); border-color: rgba(70,84,160,.12); }
body.light-theme .date-badge { color: #65709b; background: #edf1ff; box-shadow: 0 0 0 6px rgba(241,244,255,.9); }
body.light-theme .release-summary { color: #6c769d; }
body.light-theme .release-card-foot { border-top-color: rgba(76,90,160,.08); }
body.light-theme .news-editor-modal, body.light-theme .news-preview-pane { background: #f3f6ff; }
body.light-theme .news-editor-heading, body.light-theme .news-preview-pane { border-color: rgba(73,87,160,.1); }
body.light-theme .news-field input, body.light-theme .news-field select, body.light-theme .news-field textarea, body.light-theme .news-item-row { color: #28315b; background: rgba(255,255,255,.75); border-color: rgba(74,88,160,.12); }
.confirm-overlay { z-index: 5000; }

@keyframes updatesHeaderSweep { 0%,60% { transform: translateX(-110%); } 82%,100% { transform: translateX(110%); } }
@keyframes updatesSignal { 50% { opacity: .45; transform: scale(.88); } }
@keyframes timelineBeam { 0% { transform: translateY(-20%); } 100% { transform: translateY(450%); } }
@keyframes newsRowIn { from { opacity: 0; transform: translateY(7px) scale(.99); } }

@media (max-width: 940px) {
    .updates-toolbar { position: relative; top: auto; grid-template-columns: 1fr auto; }
    .updates-filters { grid-column: 1 / -1; order: 3; overflow-x: auto; padding-bottom: 2px; }
    .news-editor-layout { grid-template-columns: 1fr; overflow-y: auto; }
    .news-editor-fields { overflow: visible; }
    .news-preview-pane { display: none; }
}
@media (max-width: 620px) {
    .updates-header { grid-template-columns: 1fr; padding: 28px 22px; text-align: left; }
    .updates-header .dev-write-btn { justify-self: start; }
    .updates-overview { display: grid; grid-template-columns: repeat(3, 1fr); }
    .updates-overview div { min-width: 0; padding: 10px; }
    .updates-toolbar { grid-template-columns: 1fr; }
    .updates-sort { width: 100%; }
    .timeline-item { padding-left: 42px; margin-bottom: 18px; }
    .timeline-line { left: 12px; }
