/* ==========================================================
   Development — engineering map
   ========================================================== */
#development {
    --dev-line: rgba(255, 255, 255, .075);
    --dev-panel: rgba(10, 13, 29, .76);
    --dev-muted: #8790ae;
    --dev-soft: #b8c0dc;
}
#development .dev-layout { max-width: 1220px; padding-top: 4px; }

.dev-hero {
    position: relative;
    display: grid;
    grid-template-columns: minmax(0, 1.08fr) minmax(390px, .92fr);
    align-items: center;
    gap: clamp(34px, 6vw, 76px);
    min-height: 590px;
    padding: clamp(42px, 6vw, 72px);
    margin-bottom: 92px;
    border: 1px solid var(--dev-line);
    border-radius: 34px;
    overflow: hidden;
    isolation: isolate;
    background:
        radial-gradient(700px circle at 12% 5%, rgba(99, 102, 241, .25), transparent 62%),
        radial-gradient(520px circle at 92% 90%, rgba(46, 180, 214, .12), transparent 60%),
        linear-gradient(145deg, rgba(18, 21, 45, .94), rgba(7, 10, 24, .96));
    box-shadow: 0 34px 100px rgba(1, 3, 16, .32), inset 0 1px rgba(255, 255, 255, .05);
}
.dev-hero::before {
    content: '';
    position: absolute;
    inset: 0;
    z-index: -2;
    pointer-events: none;
    background-image: linear-gradient(rgba(149, 159, 230, .04) 1px, transparent 1px), linear-gradient(90deg, rgba(149, 159, 230, .04) 1px, transparent 1px);
    background-size: 42px 42px;
    mask-image: linear-gradient(90deg, #000, transparent 70%);
}
.dev-hero::after {
    content: '';
    position: absolute;
    z-index: -1;
    width: 310px;
    height: 310px;
    right: 9%;
    top: 14%;
    border: 1px solid rgba(137, 148, 255, .08);
    border-radius: 50%;
    box-shadow: 0 0 0 55px rgba(119, 131, 255, .025), 0 0 0 110px rgba(119, 131, 255, .018);
}
.dev-hero-copy, .dev-profile { position: relative; z-index: 2; }
.dev-eyebrow { display: inline-flex; align-items: center; gap: 9px; margin-bottom: 17px; color: #aeb8ef; font-size: .7rem; font-weight: 800; letter-spacing: .18em; text-transform: uppercase; }
.dev-eyebrow i { color: #7c8cff; }
.dev-hero h2 { max-width: 610px; margin: 0; font-size: clamp(2.75rem, 5.2vw, 4.85rem); line-height: .98; letter-spacing: -.055em; }
.dev-hero-copy > p { max-width: 600px; margin-top: 22px; color: var(--dev-soft); font-size: 1.02rem; line-height: 1.74; }
.dev-hero-actions { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 28px; }
.dev-primary-action, .dev-secondary-action {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
    height: 47px;
    padding: 0 19px;
    border-radius: 13px;
    color: #eef1ff;
    font: 700 .83rem 'Onest', sans-serif;
    text-decoration: none;
    cursor: pointer;
    transition: transform .35s var(--ease-out-back), border-color .25s ease, background .25s ease, box-shadow .3s ease;
}
.dev-primary-action { border: 1px solid rgba(140, 150, 255, .42); background: linear-gradient(135deg, #6872e7, #5360ce); box-shadow: 0 13px 34px rgba(65, 75, 207, .28), inset 0 1px rgba(255, 255, 255, .18); }
.dev-secondary-action { border: 1px solid rgba(255, 255, 255, .1); background: rgba(255, 255, 255, .045); }
.dev-primary-action:hover, .dev-secondary-action:hover { transform: translateY(-3px); }
.dev-secondary-action:hover { border-color: rgba(139, 150, 255, .27); background: rgba(109, 120, 231, .1); }

.dev-facts { display: flex; flex-wrap: wrap; gap: 0; margin-top: 38px; }
.dev-facts > span { display: grid; min-width: 92px; padding: 0 20px; border-left: 1px solid rgba(255, 255, 255, .09); }
.dev-facts > span:first-child { padding-left: 0; border-left: 0; }
.dev-facts b { color: #f4f6ff; font-size: .92rem; }
.dev-facts small { margin-top: 3px; color: #77809e; font-size: .63rem; font-weight: 600; letter-spacing: .08em; text-transform: uppercase; }

.dev-profile {
    border: 1px solid rgba(255, 255, 255, .09);
    border-radius: 24px;
    overflow: hidden;
    background: rgba(5, 8, 22, .7);
    box-shadow: 0 28px 70px rgba(0, 0, 0, .36), inset 0 1px rgba(255, 255, 255, .045);
    backdrop-filter: blur(18px);
    transform: perspective(1100px) rotateY(-3deg) rotateX(1deg);
    transition: transform .55s var(--ease-smooth), border-color .35s ease, box-shadow .45s ease;
}
.dev-profile:hover { transform: perspective(1100px) rotateY(0) rotateX(0) translateY(-4px); border-color: rgba(132, 144, 255, .22); box-shadow: 0 34px 85px rgba(15, 21, 72, .38), inset 0 1px rgba(255, 255, 255, .06); }
.dev-profile-bar { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 14px; height: 46px; padding: 0 15px; border-bottom: 1px solid rgba(255, 255, 255, .065); background: rgba(255, 255, 255, .025); }
.dev-profile-bar > span { display: flex; gap: 6px; }
