.dev-hero-orbit { position: absolute; right: -55px; bottom: -76px; width: 210px; height: 210px; z-index: 0; border: 1px dashed rgba(121, 135, 246, .13); border-radius: 50%; animation: devOrbit 24s linear infinite; }
