.tech-card-arrow { color: #59627e; font-size: .68rem; transition: transform .3s var(--ease-out-back), color .25s ease; }
.tech-card.active .tech-card-arrow { color: #8e99ff; transform: translateX(3px); }

.dev-system-panel {
    position: relative;
    min-height: 294px;
    padding: 28px;
    border: 1px solid rgba(255, 255, 255, .075);
    border-radius: 23px;
    overflow: hidden;
