}
.dev-system-panel::after { content: 'SPECTRAL / SYSTEM MAP'; position: absolute; right: 22px; bottom: 18px; color: rgba(145, 155, 207, .09); font: 700 .58rem 'Courier New', monospace; letter-spacing: .14em; }
.dev-system-panel-head { display: grid; grid-template-columns: 48px minmax(0, 1fr) auto; align-items: center; gap: 13px; }
.dev-system-panel-head > span { display: grid; place-items: center; width: 48px; height: 48px; border: 1px solid rgba(126, 139, 255, .25); border-radius: 14px; color: #9aa3ff; background: rgba(95, 108, 226, .13); }
.dev-system-panel-head > div small { display: block; color: #747e9d; font-size: .56rem; font-weight: 800; letter-spacing: .1em; text-transform: uppercase; }
.dev-system-panel-head h4 { margin-top: 3px; color: #f1f3ff; font-size: 1.15rem; }
.dev-system-panel-head > b { padding: 5px 8px; border: 1px solid rgba(126, 139, 255, .15); border-radius: 7px; color: #8c97cf; font-size: .57rem; letter-spacing: .07em; text-transform: uppercase; background: rgba(95, 108, 226, .06); }
.dev-system-panel > p { max-width: 620px; margin-top: 20px; color: #919bb8; font-size: .82rem; line-height: 1.65; }
.dev-system-contract { display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: 13px; margin-top: 20px; padding: 13px 15px; border: 1px solid rgba(255, 255, 255, .06); border-radius: 13px; background: rgba(255, 255, 255, .025); }
