.dev-system-panel ul { display: grid; gap: 7px; margin: 18px 0 0; padding: 0; list-style: none; }
.dev-system-panel li { display: flex; align-items: center; gap: 9px; color: #7f89a6; font-size: .69rem; }
.dev-system-panel li i { color: #5acda0; font-size: .58rem; }
.dev-system-panel.is-changing > * { animation: devDetailIn .38s var(--ease-smooth) both; }

.dev-workbench { display: grid; grid-template-columns: minmax(0, 1fr) 290px; gap: 14px; }
#development .code-editor { min-width: 0; margin: 0; border-radius: 22px; }
