.dev-code-notes { display: flex; flex-direction: column; min-width: 0; padding: 25px; border: 1px solid rgba(255, 255, 255, .075); border-radius: 22px; background: linear-gradient(160deg, rgba(17, 21, 45, .88), rgba(8, 11, 27, .92)); }
.dev-code-notes > span { display: flex; align-items: center; gap: 8px; color: #8390e6; font-size: .6rem; font-weight: 800; letter-spacing: .11em; text-transform: uppercase; }
