.dev-code-notes > p { margin-top: 9px; color: #858fac; font-size: .76rem; line-height: 1.62; }
.dev-code-path { display: grid; gap: 6px; margin-top: 19px; padding: 12px; border: 1px solid rgba(255, 255, 255, .06); border-radius: 11px; background: rgba(255, 255, 255, .025); }
.dev-code-path small { color: #666f8e; font-size: .54rem; font-weight: 800; letter-spacing: .09em; text-transform: uppercase; }
.dev-code-path code { overflow: hidden; color: #a9b2ef; font: 600 .62rem 'Courier New', monospace; text-overflow: ellipsis; white-space: nowrap; }
