#development .build-metrics { gap: 10px; margin-top: -40px; }
#development .bm-item { min-width: 0; padding: 17px 18px; border-radius: 15px; background: rgba(11, 14, 30, .7); }
#development .bm-icon { display: grid; place-items: center; flex: 0 0 auto; width: 36px; height: 36px; border: 1px solid rgba(126, 139, 255, .14); border-radius: 10px; color: #8692f0; font-size: .88rem; background: rgba(95, 108, 225, .07); }
#development .bm-info { min-width: 0; }
