@keyframes devOrbit { to { transform: rotate(360deg); } }
@keyframes devDetailIn { from { opacity: 0; transform: translateY(5px); } to { opacity: 1; transform: translateY(0); } }

@media (max-width: 1040px) {
    .dev-hero { grid-template-columns: 1fr 390px; gap: 32px; padding: 48px 42px; }
    .dev-hero h2 { font-size: clamp(2.7rem, 5.5vw, 4rem); }
    .dev-pipeline-track { grid-template-columns: repeat(5, minmax(150px, 1fr)); overflow-x: auto; padding-bottom: 8px; scrollbar-width: thin; }
    .dev-pipeline-track::before { min-width: 750px; }
    .dev-stage p { min-height: 70px; }
    .dev-systems-layout { grid-template-columns: 1fr; }
    #development .tech-stack-grid { grid-template-columns: repeat(3, 1fr); }
    .dev-workbench { grid-template-columns: minmax(0, 1fr) 250px; }
}
@media (max-width: 820px) {
    .dev-hero { grid-template-columns: 1fr; min-height: auto; margin-bottom: 70px; padding: 42px 30px; }
