    .dev-section-heading { grid-template-columns: 1fr; gap: 10px; }
    .dev-section-heading > p { max-width: 600px; }
    .dev-pipeline { padding: 27px 22px; }
    #development .tech-stack-grid { grid-template-columns: 1fr 1fr; }
    .dev-workbench { grid-template-columns: 1fr; }
    .dev-code-notes { min-height: 0; }
