}
@media (max-width: 560px) {
    #development .dev-layout { padding-top: 0; }
    .dev-hero { margin-inline: -2px; padding: 34px 21px 23px; border-radius: 23px; }
    .dev-hero h2 { font-size: 2.45rem; }
    .dev-hero-copy > p { font-size: .9rem; }
    .dev-hero-actions { display: grid; grid-template-columns: 1fr 1fr; }
    .dev-primary-action, .dev-secondary-action { padding: 0 12px; font-size: .75rem; }
    .dev-facts { display: grid; grid-template-columns: 1fr 1fr; gap: 15px 0; }
    .dev-facts > span:nth-child(3) { padding-left: 0; border-left: 0; }
    .dev-profile-bar { grid-template-columns: auto 1fr; }
    .dev-profile-bar > b { display: none; }
    .dev-profile-body { padding: 15px 14px 15px 28px; }
    .dev-profile-rail { left: 16px; }
    .dev-profile-layer { grid-template-columns: 36px minmax(0, 1fr); min-height: 59px; padding: 8px 10px; }
    .dev-profile-layer > span { width: 36px; height: 36px; }
    .dev-profile-layer em { font-size: .59rem; }
    .dev-profile-foot { gap: 9px 14px; }
    .dev-section-heading h3 { font-size: 1.65rem; }
    .dev-pipeline { margin-inline: -2px; padding: 24px 17px; border-radius: 21px; }
    .dev-pipeline-track { grid-template-columns: repeat(5, 160px); margin-inline: -3px; }
    .dev-stage { padding-inline: 11px; }
    .dev-principle { align-items: flex-start; }
    #development .tech-stack-grid { grid-template-columns: 1fr; }
    #development .tech-card { min-height: 78px; }
    .dev-system-panel { min-height: 0; padding: 21px; border-radius: 19px; }
    .dev-system-panel-head { grid-template-columns: 44px minmax(0, 1fr); }
    .dev-system-panel-head > b { display: none; }
    .dev-system-contract { grid-template-columns: 1fr; }
    .dev-system-contract > i { transform: rotate(90deg); }
    .dev-workbench { margin-inline: -2px; }
    #development .code-editor { border-radius: 18px; }
    #development .code-editor-header { align-items: flex-start; flex-wrap: wrap; padding: 12px; }
    #development .code-tabs { order: 3; width: 100%; overflow-x: auto; }
    #development .code-tab { flex: 0 0 auto; padding-inline: 11px; }
    #development .code-pane { min-height: 230px; padding: 22px 18px; }
    .dev-code-notes { padding: 21px; border-radius: 18px; }
    #development .build-metrics { grid-template-columns: 1fr; margin-top: -30px; }
}
@media (prefers-reduced-motion: reduce) {
    .dev-hero-orbit { animation: none; }
    .dev-profile, .dev-profile:hover { transform: none; }
}
.dev-primary-action:focus-visible, .dev-secondary-action:focus-visible, #development .tech-card:focus-visible, #development .code-tab:focus-visible { outline: 2px solid #9aa4ff; outline-offset: 3px; }

/* ==========================================================
   Subsystem atlas — connected control surface
   ========================================================== */
.dev-systems {
    position: relative;
    padding: clamp(24px, 3vw, 38px);
    border: 1px solid rgba(255, 255, 255, .075);
    border-radius: 32px;
    overflow: hidden;
    background:
        radial-gradient(700px circle at 8% 8%, rgba(93, 103, 220, .14), transparent 58%),
        radial-gradient(520px circle at 94% 92%, rgba(52, 171, 190, .075), transparent 60%),
        linear-gradient(145deg, rgba(13, 16, 35, .82), rgba(6, 9, 22, .88));
    box-shadow: 0 28px 84px rgba(1, 3, 16, .22), inset 0 1px rgba(255, 255, 255, .04);
}
.dev-systems::before {
    content: '';
    position: absolute;
    inset: 0;
    pointer-events: none;
