/* ============================================================
   PROFILE PREFERENCES
   ============================================================ */
.profile-preferences {
    margin: 20px 0 24px;
    padding: 15px;
    border: 1px solid rgba(129, 140, 248, .13);
    border-radius: 18px;
    background: linear-gradient(145deg, rgba(99, 102, 241, .075), rgba(255, 255, 255, .022));
}
.profile-preferences-head { display: flex; align-items: center; gap: 11px; margin-bottom: 12px; }
.profile-preferences-head > span {
    display: grid; place-items: center; flex: 0 0 34px; width: 34px; height: 34px;
    border-radius: 10px; color: #a5b4fc; background: rgba(99, 102, 241, .13);
}
.profile-preferences-head h4 { margin: 0; color: #eef2ff; font-size: .82rem; }
.profile-preferences-head p { margin: 2px 0 0; color: #727d98; font-size: .61rem; line-height: 1.35; }
.profile-preference-list { display: grid; gap: 8px; }
.profile-preference-row {
    display: grid; grid-template-columns: 38px minmax(0, 1fr) auto; align-items: center; gap: 10px;
    min-height: 58px; padding: 9px 11px; border: 1px solid rgba(255, 255, 255, .065);
    border-radius: 13px; background: rgba(3, 6, 18, .24); cursor: pointer;
    transition: border-color .2s ease, background .2s ease, transform .25s var(--ease-out-back);
}
.profile-preference-row:hover { transform: translateY(-1px); border-color: rgba(129, 140, 248, .22); background: rgba(99, 102, 241, .065); }
.profile-preference-icon { display: grid; place-items: center; width: 38px; height: 38px; border-radius: 11px; color: #a5b4fc; background: rgba(99, 102, 241, .12); }
.profile-preference-icon.performance { color: #6ee7b7; background: rgba(16, 185, 129, .1); }
.profile-preference-copy { display: grid; min-width: 0; }
.profile-preference-copy strong { color: #e8ecf8; font-size: .73rem; }
.profile-preference-copy small { margin-top: 2px; color: #768199; font-size: .58rem; line-height: 1.35; }
.profile-preference-input { position: absolute; width: 1px; height: 1px; opacity: 0; pointer-events: none; }
.profile-preference-switch {
    position: relative; width: 42px; height: 24px; border: 1px solid rgba(148, 163, 184, .24);
    border-radius: 999px; background: rgba(71, 85, 105, .35); transition: background .22s ease, border-color .22s ease;
}
.profile-preference-switch i {
    position: absolute; left: 3px; top: 3px; width: 16px; height: 16px; border-radius: 50%;
    background: #cbd5e1; box-shadow: 0 2px 7px rgba(0, 0, 0, .3); transition: transform .25s var(--ease-out-back), background .2s ease;
}
.profile-preference-input:checked + .profile-preference-switch { border-color: rgba(129, 140, 248, .65); background: linear-gradient(135deg, #6366f1, #4f46e5); }
.profile-preference-input:checked + .profile-preference-switch i { transform: translateX(18px); background: #fff; }
.profile-preference-input:focus-visible + .profile-preference-switch { outline: 2px solid #a5b4fc; outline-offset: 3px; }
.profile-performance-note { display: flex; align-items: flex-start; gap: 8px; margin: 11px 2px 0; color: #68748e; font-size: .57rem; line-height: 1.45; }
.profile-performance-note i { margin-top: 2px; color: #818cf8; }
body.light-theme .profile-preferences { border-color: rgba(79, 70, 229, .14); background: linear-gradient(145deg, rgba(99, 102, 241, .075), rgba(255, 255, 255, .65)); }
body.light-theme .profile-preferences-head h4, body.light-theme .profile-preference-copy strong { color: #252850; }
body.light-theme .profile-preferences-head p, body.light-theme .profile-preference-copy small, body.light-theme .profile-performance-note { color: #71779a; }
body.light-theme .profile-preference-row { border-color: rgba(79, 70, 229, .1); background: rgba(255, 255, 255, .58); }
body.light-theme .profile-preference-row:hover { border-color: rgba(79, 70, 229, .22); background: rgba(99, 102, 241, .07); }

