    .active-account-uuid span { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
    .active-account-stats { display: grid; grid-template-columns: 1fr 1fr; width: 100%; gap: 9px; }
    .acc-stat { width: 100%; min-width: 0; }

    .updates-header { width: 100%; padding: 22px 18px; }
    .updates-heading-copy, .updates-overview, .updates-featured { width: 100%; min-width: 0; }
    .updates-overview { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 6px; }
    .updates-overview div { min-width: 0; padding: 9px 5px; }
    .updates-overview strong { font-size: .9rem; }
    .updates-overview span { font-size: .5rem; }
    .updates-featured { min-height: 0; padding: 18px; }
    .updates-featured-meta, .updates-featured-actions { flex-wrap: wrap; }
    .updates-featured-actions > * { flex: 1 1 130px; }
    .updates-timeline { width: 100%; padding-inline: 0; }
    .timeline-item { width: 100%; padding-left: 42px; }
    .timeline-card { width: 100% !important; margin: 0 !important; }
    .release-card-main { min-width: 0; }
    .release-card-main h3, .release-summary { overflow-wrap: anywhere; }
    .release-details-content { padding-left: 18px; padding-right: 18px; }
    .release-card-foot { flex-wrap: wrap; gap: 8px; }

    .dev-hero-orbit { display: none; }
    .dev-pipeline { padding: 20px 16px; }
    .dev-pipeline-track { grid-template-columns: minmax(0, 1fr); gap: 8px; margin: 0; padding: 0; overflow: visible; }
    .dev-pipeline-track::before { left: 35px; right: auto; top: 34px; bottom: 34px; width: 1px; height: auto; min-width: 0; }
    .dev-stage {
        display: grid; grid-template-columns: 42px minmax(0, 1fr);
        grid-template-areas: "icon number" "icon title" "icon copy" "icon tag";
        column-gap: 14px; min-width: 0; padding: 14px 12px;
    }
    .dev-stage-number { grid-area: number; margin: 0 0 3px; align-self: end; }
    .dev-stage > i { grid-area: icon; margin: 2px 0 0; align-self: start; }
    .dev-stage h4 { grid-area: title; margin: 0 0 4px; }
    .dev-stage p { grid-area: copy; min-height: 0; margin: 0; }
    .dev-stage small { grid-area: tag; justify-self: start; margin-top: 8px; }
    .dev-principle { margin-top: 14px; }
    .dev-system-content, .dev-systems-layout, .dev-workbench { grid-template-columns: minmax(0, 1fr) !important; }
    .code-editor-bar { align-items: flex-start; }
    .code-tabs { width: 100%; flex-wrap: wrap; overflow: visible; }
    .code-tab { flex: 1 1 calc(50% - 4px); min-width: 0; }
    .code-content { max-width: 100%; overflow-x: auto; }

    .profile-header { padding-right: 34px; }
    .profile-stat-chips { gap: 7px; }
    .p-stat-chip { flex: 1 1 calc(50% - 7px); min-width: 0; justify-content: center; }
    .profile-preferences { padding: 12px; }
    .profile-preference-row { grid-template-columns: 38px minmax(0, 1fr) auto; padding-inline: 9px; }

    .lite-banner { bottom: 12px; flex-wrap: wrap; }
    .lite-banner .lite-banner-actions { width: 100%; justify-content: flex-end; }
    .scroll-to-top { right: 14px; bottom: 14px; }
}

@media (max-width: 420px) {
    .content-wrapper { padding-inline: 12px; }
    .navbar { padding-inline: 12px; }
    .logo-text { display: none; }
    .hero-text-block h1 { font-size: clamp(1.82rem, 9vw, 2.25rem); }
    .hero-text-block p { font-size: .93rem; }
    .cta-group { grid-template-columns: 1fr; }
    .stats-row { margin-inline: 0; }
