}

body.light-theme .feature-card,
body.light-theme .account-card,
body.light-theme .acc-panel,
body.light-theme .accounts-stats-strip,
body.light-theme .support-channel,
body.light-theme .fix-card,
body.light-theme .faq-item,
body.light-theme .forum-post-card,
body.light-theme .forum-empty-state,
body.light-theme .af-card,
body.light-theme .tech-card,
body.light-theme .dev-pipeline,
body.light-theme .dev-profile,
body.light-theme .dev-system-panel,
body.light-theme .dev-code-notes,
body.light-theme .code-editor,
