}

body.light-theme .nav-links-container.glass {
    border-color: var(--material-border);
    background:
        linear-gradient(135deg, rgba(255, 255, 255, .9), transparent 38%),
        linear-gradient(150deg, var(--material-surface-strong-a), var(--material-surface-strong-b));
    box-shadow: var(--material-shadow-soft);
}

body.light-theme .dashboard-modal.glass-modal,
body.light-theme .add-account-modal.glass-modal,
