}

/* Mobile glass is a little calmer so text stays crisp on small screens. */
@media (max-width: 620px) {
    :root {
        --material-blur: blur(17px) saturate(128%);
        --material-blur-strong: blur(22px) saturate(134%);
        --material-shadow: 0 18px 48px rgba(0, 0, 0, .24), inset 0 1px var(--material-highlight);
        --material-shadow-soft: 0 11px 30px rgba(0, 0, 0, .15), inset 0 1px rgba(255, 255, 255, .05);
        --material-radius-xl: 24px;
        --material-radius-lg: 19px;
    }

    .updates-header,
    .dev-hero,
    .af-showcase,
    .support-cta,
    .active-account-banner { border-radius: var(--material-radius-xl); }

    .feature-card,
    .account-card,
    .acc-panel,
    .support-channel,
    .fix-card,
    .af-card,
    .timeline-card,
    .dev-pipeline,
    .dev-system-panel { border-radius: var(--material-radius-lg); }
}

/* Lightweight mode keeps the hierarchy, but removes GPU-heavy optics. */
html.lite-mode {
    --material-surface-a: #111522;
