/* ============================================================
   MOTION SYSTEM V3 — COMPOSITOR-FIRST AND FRAME-COHERENT
   ============================================================ */
:root {
    --motion-fast: 180ms;
    --motion-normal: 320ms;
    --motion-slow: 560ms;
    --motion-reveal: 680ms;
    --motion-ease: cubic-bezier(.2, .72, .25, 1);
    --motion-ease-out: cubic-bezier(.16, 1, .3, 1);
    --motion-ease-soft: cubic-bezier(.33, 1, .68, 1);
}

.tab-content { transform: translate3d(0, 12px, 0); transition: opacity var(--motion-normal) ease, transform 440ms var(--motion-ease-out); }
.animate-on-scroll { opacity: 0; transform: translate3d(0, 18px, 0); transition: opacity var(--motion-reveal) ease, transform var(--motion-reveal) var(--motion-ease-out); will-change: opacity, transform; }
.animate-on-scroll.visible { opacity: 1; transform: translate3d(0, 0, 0); will-change: auto; }
.delay-1 { transition-delay: 55ms; }
.delay-2 { transition-delay: 110ms; }
.delay-3 { transition-delay: 165ms; }
.delay-4 { transition-delay: 220ms; }

.feature-card,
.account-card,
.support-channel,
.fix-card,
.forum-post-card,
.af-card,
.tech-card,
.timeline-card,
.btn-primary,
.btn-secondary,
.nav-btn { backface-visibility: hidden; transform: translateZ(0); }

.motion-pulse { animation: motionStatusPulse 2.4s ease-in-out infinite; transform-origin: center; }
.ambient-light { animation-duration: 34s; }
.bg-gradient-overlay { animation-duration: 28s; }
.bg-gradient-overlay::before,
.spectral-horizon,
.lu-hero-bg::after { animation: none !important; }
.bg-gradient-overlay::after { animation: motionDustFloat 30s ease-in-out infinite alternate; will-change: transform, opacity; }
.spectral-core,
.spectral-ring,
.spectral-prism,
.lu-cube,
.lu-cube-cluster { backface-visibility: hidden; }

/* Scroll state is class-driven, keeping navbar movement on the compositor. */
.navbar { will-change: transform; }
.navbar.is-hidden { transform: translate3d(0, -100%, 0); }
.navbar.is-scrolled { transform: translate3d(0, 0, 0); background: rgba(5, 5, 7, .95); box-shadow: 0 4px 30px rgba(0, 0, 0, .3); }
body.light-theme .navbar.is-scrolled { background: rgba(234, 236, 252, .92); box-shadow: 0 4px 30px rgba(99, 102, 241, .12); }

/* Positional shine sweeps now animate with transforms instead of layout. */
.nav-btn::before { left: 0; transform: translate3d(-110%, 0, 0); transition: transform var(--motion-slow) var(--motion-ease-out); }
.nav-btn:hover::before { left: 0; transform: translate3d(110%, 0, 0); }
.acc-btn-select::after { left: 0; transform: translate3d(-140%, 0, 0); transition: transform var(--motion-slow) var(--motion-ease-out); }
.acc-btn-select:hover::after { left: 0; transform: translate3d(255%, 0, 0); }

/* Static large gradients avoid full-surface repaints; compact signals retain motion. */
.text-gradient,
.timeline-card.is-current::before,
.tag.new { animation: none; }
.pulse-dot,
.lu-dot,
.term-live-dot { animation: motionStatusPulse 2.4s ease-in-out infinite; }
.tech-bar div,
.dist-fill { transition: none; }

/* Keep the few necessary layout transitions locally contained. */
#home .features-grid { contain: layout; }
.active-account-banner,
.af-feature-map,
.role-store-hero,
.faq-item,
.release-details { contain: layout paint; }

/* One-shot code reveal and launcher orbit avoid clip/position animation. */
.code-pane--in { animation: motionCodeReveal var(--motion-slow) var(--motion-ease-out) both; }
.code-pane--in::after { left: 0; width: 100%; background: linear-gradient(90deg, transparent 44%, rgba(129, 140, 248, .28) 50%, transparent 56%); animation: motionCodeScan var(--motion-slow) var(--motion-ease-out) both; }
.lu-orbit span { left: 42%; top: -3px; animation: motionOrbitTravel 4s ease-in-out infinite; }

.faq-a { display: grid; grid-template-rows: 0fr; max-height: none !important; overflow: hidden; transition: grid-template-rows var(--motion-normal) var(--motion-ease); }
.faq-a p { min-height: 0; overflow: hidden; }
.faq-item.open .faq-a { grid-template-rows: 1fr; }

html.motion-paused *,
html.motion-paused *::before,
html.motion-paused *::after { animation-play-state: paused !important; }

@keyframes afRingBreathe { 0%, 100% { opacity: .3; transform: translate3d(-50%, -50%, 0) scale(.985); } 50% { opacity: .58; transform: translate3d(-50%, -50%, 0) scale(1.025); } }
@keyframes motionStatusPulse { 0%, 100% { opacity: .65; transform: scale(.82); } 50% { opacity: 1; transform: scale(1); } }
@keyframes motionDustFloat { from { opacity: .5; transform: translate3d(-1.5%, 0, 0); } to { opacity: .75; transform: translate3d(1.5%, -1%, 0); } }
@keyframes motionCodeReveal { from { opacity: 0; transform: translate3d(0, 8px, 0); } to { opacity: 1; transform: translate3d(0, 0, 0); } }
@keyframes motionCodeScan { from { transform: translate3d(-100%, 0, 0); } to { transform: translate3d(100%, 0, 0); } }
@keyframes motionOrbitTravel { 0%, 100% { opacity: .75; transform: translate3d(0, 0, 0); } 50% { opacity: 1; transform: translate3d(40px, 0, 0); } }
@keyframes pageAuroraShift { from { transform: scale(1); } to { transform: scale(1.018); } }
@keyframes luBackgroundBreath { from { transform: scale(1); } to { transform: scale(1.018); } }

@media (hover: none), (pointer: coarse) {
    .feature-card:hover,
    .account-card:hover,
    .support-channel:hover,
    .fix-card:hover,
    .forum-post-card:hover,
    .af-card:hover,
    .tech-card:hover,
    .timeline-card:hover { transform: none; }
    .af-map-node { -webkit-backdrop-filter: none; backdrop-filter: none; }
}

@media (prefers-reduced-motion: reduce) {
    html { scroll-behavior: auto !important; }
    *, *::before, *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; transition-delay: 0ms !important; }
    .animate-on-scroll, .timeline-item, .code-pane { opacity: 1 !important; transform: none !important; }
}

html.lite-mode .af-feature-map::before,
html.lite-mode .af-feature-map::after,
html.lite-mode .af-map-grid,
html.lite-mode .af-card-glow { display: none !important; }
html.lite-mode .af-feature-map,
html.lite-mode .af-map-node,
html.lite-mode .af-map-status,
html.lite-mode .af-mini-console,
html.lite-mode .af-instance-preview span,
html.lite-mode #advanced-features .af-stats-strip { background-image: none !important; background-color: var(--material-surface-a) !important; box-shadow: none !important; }
html.lite-mode #advanced-features .af-bar-fill { transform: scaleX(var(--bar-progress, 0)); }
/* ============================================================
   COMPOSITION V4 — ACCOUNTS COCKPIT + SUPPORT DIAGNOSTICS
   ============================================================ */
.accounts-section,
.support-wrapper { max-width: 1240px; }

/* Accounts is presented as an identity route, not a stack of cards. */
.accounts-command-hero {
    display: grid;
    grid-template-columns: minmax(0, .9fr) minmax(430px, 1.1fr);
    grid-template-areas: 'copy route' 'actions route';
    align-items: center;
    gap: 18px 56px;
    margin-bottom: 28px;
    padding: clamp(34px, 5vw, 62px);
    border: 1px solid var(--material-border);
    border-radius: 32px;
    overflow: hidden;
    background:
        radial-gradient(600px circle at 3% 0%, rgba(99, 102, 241, .22), transparent 65%),
        radial-gradient(480px circle at 100% 100%, rgba(34, 168, 208, .11), transparent 68%),
        linear-gradient(145deg, var(--material-surface-strong-a), var(--material-surface-strong-b));
    box-shadow: var(--material-shadow);
}
.accounts-command-hero > div:first-child { grid-area: copy; }
