.accounts-identity-route { position: relative; min-height: 360px; display: grid; align-content: center; gap: 10px; padding: 28px 24px 70px 34px; border: 1px solid rgba(133, 145, 238, .11); border-radius: 24px; background: linear-gradient(155deg, rgba(11, 15, 37, .76), rgba(6, 9, 23, .62)); box-shadow: inset 0 1px rgba(255, 255, 255, .045); }
