    padding: 28px;
    transition:
        width .56s cubic-bezier(.16, 1, .3, 1),
        max-width .56s cubic-bezier(.16, 1, .3, 1),
        padding .48s cubic-bezier(.16, 1, .3, 1),
        border-radius .48s ease,
        background .42s ease,
        box-shadow .48s ease,
        transform .4s var(--ease-out-back);
