/* The admin shell now settles on the compositor; no width repaint on every frame. */
.dashboard-modal.profile-wide {
    transition: border-color .24s ease, background .24s ease, box-shadow .24s ease !important;
}
.dashboard-modal.profile-wide.dashboard-morphing {
    overflow: hidden;
    animation: dashboardShellSettle .30s cubic-bezier(.16, 1, .3, 1) both;
}
.dashboard-modal.profile-wide.admin-wide .ptab-content.ptab-enter {
    animation: adminPanelReveal .30s cubic-bezier(.16, 1, .3, 1) both;
}
@keyframes dashboardShellSettle {
    from { opacity: .94; transform: translate3d(0, 3px, 0) scale(.992); }
    to { opacity: 1; transform: translate3d(0, 0, 0) scale(1); }
}
@keyframes adminPanelReveal {
    from { opacity: 0; transform: translate3d(0, 8px, 0); }
    to { opacity: 1; transform: translate3d(0, 0, 0); }
}

