/* ═══════════════════════════════════════════════════════════════════════════
   PROFILE IDENTITY STUDIO · ROLE LAB · UNIFIED SCROLL SYSTEM
   ═══════════════════════════════════════════════════════════════════════════ */
:root {
    --scroll-track: rgba(8, 10, 20, .72);
    --scroll-thumb-a: #5361d8;
    --scroll-thumb-b: #8b5cf6;
    --scroll-thumb-c: #22b8cf;
}
html { scrollbar-width: auto; scrollbar-color: var(--scroll-thumb-b) var(--scroll-track); }
* { scrollbar-width: thin; scrollbar-color: rgba(116, 99, 232, .78) rgba(13, 15, 27, .48); }
html::-webkit-scrollbar { width: 15px; height: 15px; }
*::-webkit-scrollbar { width: 11px; height: 11px; }
html::-webkit-scrollbar-track,
*::-webkit-scrollbar-track {
    border-radius: 999px;
    background: linear-gradient(180deg, rgba(5, 7, 14, .9), rgba(14, 16, 30, .72));
    box-shadow: inset 0 0 0 1px rgba(139, 148, 255, .055);
}
html::-webkit-scrollbar-thumb,
*::-webkit-scrollbar-thumb {
    min-height: 44px;
    border: 3px solid transparent;
    border-radius: 999px;
    background: linear-gradient(180deg, var(--scroll-thumb-a), var(--scroll-thumb-b) 54%, var(--scroll-thumb-c));
    background-clip: padding-box;
    box-shadow: inset 0 0 0 1px rgba(255,255,255,.16), 0 0 16px rgba(103, 89, 225, .22);
}
html::-webkit-scrollbar-thumb:hover,
*::-webkit-scrollbar-thumb:hover {
    border-width: 2px;
    background: linear-gradient(180deg, #6875ef, #9a6dff 55%, #35cee0);
    background-clip: padding-box;
}
html::-webkit-scrollbar-thumb:active,
*::-webkit-scrollbar-thumb:active {
    background: linear-gradient(180deg, #7c87ff, #ad7cff 58%, #4be1ee);
    background-clip: padding-box;
}
*::-webkit-scrollbar-corner { background: rgba(7, 9, 17, .9); }
*::-webkit-scrollbar-button { width: 0; height: 0; display: none; }
.feature-benefits { scrollbar-width: thin; }
.feature-benefits::-webkit-scrollbar { display:block; height:8px; }
.dashboard-modal::-webkit-scrollbar { width: 12px; }
.dashboard-modal::-webkit-scrollbar-track { margin-block: 24px; }
.dashboard-modal::-webkit-scrollbar-thumb { border-width: 3px; }
body.light-theme {
    --scroll-track: rgba(225, 228, 246, .8);
    --scroll-thumb-a: #5967d7;
    --scroll-thumb-b: #7c4ed2;
    --scroll-thumb-c: #149ab5;
    scrollbar-color: #7c4ed2 rgba(225,228,246,.8);
}
body.light-theme * { scrollbar-color: rgba(103, 80, 197, .76) rgba(225,228,246,.72); }
body.light-theme html::-webkit-scrollbar-track,
body.light-theme *::-webkit-scrollbar-track { background: linear-gradient(180deg,#eceefa,#dfe3f5); box-shadow: inset 0 0 0 1px rgba(74,63,145,.08); }

.dashboard-modal.profile-wide:not(.admin-wide):not(.store-wide) {
    width: min(980px, calc(100vw - 34px));
    max-width: none;
    padding: 30px;
    border-radius: 29px;
    background:
        radial-gradient(700px circle at 0 0, rgba(86, 92, 215, .18), transparent 58%),
        radial-gradient(520px circle at 100% 12%, rgba(30, 174, 196, .07), transparent 62%),
        linear-gradient(145deg, rgba(14, 17, 35, .985), rgba(6, 8, 19, .99));
    box-shadow: 0 42px 125px rgba(0,0,0,.58), inset 0 1px rgba(255,255,255,.08);
}
.dashboard-modal.profile-wide {
    transition: width .58s cubic-bezier(.16,1,.3,1), max-width .58s cubic-bezier(.16,1,.3,1), padding .5s cubic-bezier(.16,1,.3,1), border-radius .45s ease, border-color .35s ease, background .45s ease, box-shadow .45s ease, transform .5s cubic-bezier(.16,1,.3,1) !important;
}
