.profile-cover {
    --header-a: #555fd5;
    --header-b: #7254ca;
    --header-c: #22a8c4;
    grid-area: header;
    position: relative;
    min-height: 238px;
    overflow: hidden;
    isolation: isolate;
    border: 1px solid color-mix(in srgb, var(--header-a) 38%, transparent);
    border-radius: 24px;
    background:
        radial-gradient(circle at 76% 22%, color-mix(in srgb,var(--header-c) 31%,transparent), transparent 31%),
        radial-gradient(circle at 16% 5%, color-mix(in srgb,var(--header-a) 35%,transparent), transparent 40%),
        linear-gradient(135deg, color-mix(in srgb,var(--header-a) 27%,#0a0d1a), #090b14 58%, color-mix(in srgb,var(--header-b) 20%,#070912));
    box-shadow: inset 0 1px rgba(255,255,255,.075), 0 20px 42px rgba(0,0,0,.2);
    transition: border-color .5s ease, box-shadow .5s ease, background .7s ease;
