.profile-cover[data-header="archive"] { --header-a:#14b8a6; --header-b:#0f766e; --header-c:#5eead4; }
.profile-cover[data-header="solar"] { --header-a:#f59e0b; --header-b:#b45309; --header-c:#fde68a; }
.profile-cover[data-header="crown"] { --header-a:#8b5cf6; --header-b:#5b21b6; --header-c:#d8b4fe; }
.profile-cover[data-header="prism"] { --header-a:#22d3ee; --header-b:#8b5cf6; --header-c:#ec4899; }
.profile-cover[data-header="guardian"] { --header-a:#3b82f6; --header-b:#1d4ed8; --header-c:#7dd3fc; }
.profile-cover[data-header="command"] { --header-a:#ef4444; --header-b:#991b1b; --header-c:#fb7185; }
.profile-cover[data-header="code"] { --header-a:#ec4899; --header-b:#7c3aed; --header-c:#22d3ee; }
.profile-cover::before {
    content:"";
    position:absolute;
    inset:0;
    z-index:-2;
    opacity:.35;
    background-image: linear-gradient(rgba(255,255,255,.045) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.045) 1px,transparent 1px);
    background-size:32px 32px;
    mask-image:linear-gradient(90deg,transparent,#000 22%,#000 82%,transparent);
    animation:profileHeaderGrid 16s linear infinite;
}
.profile-cover::after {
    content:"";
    position:absolute;
    inset:auto 0 0;
    z-index:-1;
    height:68%;
    background:linear-gradient(transparent,rgba(6,8,18,.84) 76%,rgba(6,8,18,.96));
}
.profile-cover-scene { position:absolute; inset:0; z-index:-1; overflow:hidden; pointer-events:none; }
.profile-cover-scene i { position:absolute; width:230px; height:230px; border:1px solid color-mix(in srgb,var(--header-c) 24%,transparent); border-radius:50%; animation:profileHeaderOrbit 15s linear infinite; }
.profile-cover-scene i::after { content:""; position:absolute; top:47%; left:-4px; width:8px; height:8px; border-radius:50%; background:var(--header-c); box-shadow:0 0 18px var(--header-c); }
.profile-cover-scene i:nth-child(1) { top:-126px; right:9%; }
.profile-cover-scene i:nth-child(2) { width:330px; height:330px; top:-175px; right:1%; opacity:.55; animation-duration:24s; animation-direction:reverse; }
.profile-cover-scene i:nth-child(3) { width:110px; height:110px; top:35px; right:22%; opacity:.34; animation-duration:10s; }
.profile-cover-scene span,.profile-cover-scene b { position:absolute; display:block; border-radius:999px; filter:blur(35px); opacity:.2; }
.profile-cover-scene span { width:240px; height:80px; top:15px; left:8%; background:var(--header-a); animation:profileHeaderDrift 7s ease-in-out infinite alternate; }
.profile-cover-scene b { width:180px; height:90px; top:48px; right:6%; background:var(--header-c); animation:profileHeaderDrift 9s -2s ease-in-out infinite alternate-reverse; }
.profile-cover[data-header="solar"] .profile-cover-scene i,
.profile-cover[data-header="command"] .profile-cover-scene i { border-style:dashed; }
.profile-cover[data-header="prism"] .profile-cover-scene span { background:linear-gradient(90deg,#22d3ee,#8b5cf6,#ec4899); opacity:.38; width:380px; }
.profile-cover[data-header="code"]::before { background-image:linear-gradient(rgba(236,72,153,.055) 1px,transparent 1px),linear-gradient(90deg,rgba(34,211,238,.05) 1px,transparent 1px); background-size:18px 18px; }
.profile-cover[data-header="code"] .profile-cover-scene::after { content:"0101  SPECTRAL  1100  BUILD  0110  ROLE  1011"; position:absolute; top:48px; left:7%; width:86%; color:rgba(244,114,182,.2); font:700 .62rem 'Courier New',monospace; letter-spacing:.3em; white-space:nowrap; animation:codeTraceSlide 8s linear infinite; }
.profile-cover[data-header="guardian"]::before,.profile-cover[data-header="command"]::before { animation-duration:7s; }
.profile-cover.header-switching .profile-cover-scene { animation:headerSceneSwitch .7s cubic-bezier(.16,1,.3,1) both; }
@keyframes profileHeaderGrid { to { background-position:32px 32px; } }
@keyframes profileHeaderOrbit { to { transform:rotate(360deg); } }
