/* Distinct, smooth profile-menu entrances. */
.dashboard-modal.profile-wide.profile-opening { transform-origin:50% 46%; }
.dashboard-modal.profile-wide.profile-opening[data-entrance="signal"] { animation:profileSignalEntrance .78s cubic-bezier(.16,1,.3,1) both; }
.dashboard-modal.profile-wide.profile-opening[data-entrance="aurora"] { animation:profileAuroraEntrance .86s cubic-bezier(.16,1,.3,1) both; }
.dashboard-modal.profile-wide.profile-opening[data-entrance="portal"] { animation:profilePortalEntrance .9s cubic-bezier(.16,1,.3,1) both; }
.dashboard-modal.profile-wide.profile-opening[data-entrance="stardust"] { animation:profileStardustEntrance .95s cubic-bezier(.16,1,.3,1) both; }
.dashboard-modal.profile-wide.profile-opening[data-entrance="rift"] { animation:profileRiftEntrance 1s cubic-bezier(.16,1,.3,1) both; }
.dashboard-modal.profile-wide.profile-opening[data-entrance="terminal"] { animation:profileTerminalEntrance .86s cubic-bezier(.16,1,.3,1) both; }
.dashboard-modal.profile-wide.profile-opening::before { content:""; position:absolute; inset:-2px; z-index:20; pointer-events:none; border-radius:inherit; background:linear-gradient(115deg,transparent 18%,rgba(129,140,248,.24),transparent 48%); transform:translateX(-120%); animation:profileMenuScan .9s .08s ease-out both; }
.dashboard-modal.profile-wide.profile-opening #profileView > .profile-tabs,
.dashboard-modal.profile-wide.profile-opening [data-ptab-content="my-profile"] > * { animation:profilePieceReveal .62s cubic-bezier(.16,1,.3,1) both; }
.dashboard-modal.profile-wide.profile-opening [data-ptab-content="my-profile"] > :nth-child(1) { animation-delay:.08s; }
.dashboard-modal.profile-wide.profile-opening [data-ptab-content="my-profile"] > :nth-child(2) { animation-delay:.13s; }
.dashboard-modal.profile-wide.profile-opening [data-ptab-content="my-profile"] > :nth-child(3) { animation-delay:.17s; }
.dashboard-modal.profile-wide.profile-opening [data-ptab-content="my-profile"] > :nth-child(4) { animation-delay:.21s; }
.dashboard-modal.profile-wide.profile-opening [data-ptab-content="my-profile"] > :nth-child(5) { animation-delay:.25s; }
@keyframes profileSignalEntrance { from { opacity:0; transform:translate3d(0,24px,0) scale(.92); filter:blur(13px); } 58% { opacity:1; } to { opacity:1; transform:none; filter:blur(0); } }
@keyframes profileAuroraEntrance { from { opacity:0; clip-path:inset(0 42% 0 42% round 30px); transform:translateY(20px) scale(.96); filter:hue-rotate(45deg) blur(9px); } to { opacity:1; clip-path:inset(0 round 29px); transform:none; filter:none; } }
@keyframes profilePortalEntrance { from { opacity:0; transform:perspective(1100px) rotateX(16deg) rotateY(-9deg) translateY(28px) scale(.88); filter:blur(11px); } to { opacity:1; transform:perspective(1100px) rotateX(0) rotateY(0) translateY(0) scale(1); filter:blur(0); } }
@keyframes profileStardustEntrance { 0% { opacity:0; transform:scale(.76) rotate(-2deg); filter:blur(17px) brightness(1.7); } 60% { opacity:1; transform:scale(1.025); } 100% { opacity:1; transform:scale(1); filter:none; } }
@keyframes profileRiftEntrance { 0% { opacity:0; clip-path:polygon(49% 0,51% 0,55% 100%,45% 100%); transform:scale(.9); filter:blur(12px) saturate(1.7); } 72% { opacity:1; clip-path:polygon(0 0,100% 0,100% 100%,0 100%); } 100% { opacity:1; clip-path:inset(0 round 29px); transform:scale(1); filter:none; } }
@keyframes profileTerminalEntrance { from { opacity:0; clip-path:inset(0 0 94% 0 round 29px); transform:translateY(-12px); filter:brightness(1.5); } to { opacity:1; clip-path:inset(0 round 29px); transform:none; filter:none; } }
@keyframes profileMenuScan { to { transform:translateX(120%); opacity:0; } }
@keyframes profilePieceReveal { from { opacity:0; transform:translateY(12px) scale(.985); filter:blur(5px); } to { opacity:1; transform:none; filter:none; } }

body.light-theme .dashboard-modal.profile-wide:not(.admin-wide):not(.store-wide) { background:radial-gradient(circle at 0 0,rgba(99,102,241,.13),transparent 55%),linear-gradient(145deg,#fafbff,#eff2ff); }
