@media (max-width: 1020px) {
    .dashboard-modal.profile-wide:not(.admin-wide):not(.store-wide) { width:calc(100vw - 22px); padding:25px; }
    .profile-header-options { grid-template-columns:repeat(2,minmax(0,1fr)); }
    .role-store-grid.developer-grid { grid-template-columns:repeat(3,minmax(0,1fr)); }
}
@media (max-width: 820px) {
    .dashboard-modal.profile-wide .ptab-content[data-ptab-content="my-profile"] { grid-template-columns:1fr; grid-template-areas:"header" "stats" "role" "studio" "preferences" "settings" "actions"; }
    .profile-cover { min-height:270px; }
    .profile-cover-signal { display:none; }
    .developer-role-lab { grid-template-columns:52px minmax(0,1fr); }
    .developer-role-lab-state { grid-column:1/3; grid-template-columns:1fr auto; align-items:center; }
    .developer-role-lab-state > small { display:none; }
    .role-store-grid.developer-grid { grid-template-columns:repeat(2,minmax(0,1fr)); }
}
@media (max-width: 620px) {
    html::-webkit-scrollbar { width:10px; height:10px; }
