/* The active segment travels between tabs instead of flashing in place. */
#profileTabs {
    --tab-count: 2;
    --tab-offset: 0%;
    position: relative;
    isolation: isolate;
    overflow: hidden;
    gap: 0;
}
#profileTabs::before {
    content: "";
    position: absolute;
    z-index: 0;
    inset: 5px auto 5px 5px;
    width: calc((100% - 10px) / var(--tab-count));
    border: 1px solid rgba(139, 148, 255, .30);
    border-radius: 11px;
    background: linear-gradient(135deg, rgba(99, 102, 241, .42), rgba(80, 104, 219, .22));
    box-shadow: 0 8px 24px rgba(52, 61, 167, .18), inset 0 1px rgba(255, 255, 255, .10);
    transform: translate3d(var(--tab-offset), 0, 0);
    transition: transform .52s cubic-bezier(.16, 1, .3, 1), width .45s cubic-bezier(.16, 1, .3, 1), border-color .3s ease, background .3s ease;
    pointer-events: none;
}
#profileTabs .profile-tab {
    position: relative;
    z-index: 1;
    color: #8791aa;
    background: transparent !important;
    box-shadow: none !important;
    transition: color .34s ease, transform .34s cubic-bezier(.16, 1, .3, 1), text-shadow .34s ease;
}
#profileTabs .profile-tab:hover { color: #cbd1e4; transform: translateY(-1px); }
#profileTabs .profile-tab.active { color: #f5f6ff; text-shadow: 0 0 18px rgba(165, 180, 252, .28); }

