@keyframes accountPanelGlideIn {
    from { opacity: 0; transform: translate3d(0, 12px, 0) scale(.992); }
    to { opacity: 1; transform: translate3d(0, 0, 0) scale(1); }
}
@keyframes profileSignalEntrance {
    from { opacity: 0; transform: translate3d(0, 18px, 0) scale(.96); }
    to { opacity: 1; transform: translate3d(0, 0, 0) scale(1); }
}
@keyframes profileAuroraEntrance {
    from { opacity: 0; transform: translate3d(-18px, 12px, 0) scale(.965); }
    to { opacity: 1; transform: translate3d(0, 0, 0) scale(1); }
}
@keyframes profilePortalEntrance {
    from { opacity: 0; transform: perspective(1100px) translate3d(0, 20px, 0) rotateX(5deg) scale(.94); }
    to { opacity: 1; transform: perspective(1100px) translate3d(0, 0, 0) rotateX(0) scale(1); }
}
@keyframes profileStardustEntrance {
