#accounts.account-cockpit-tab { overflow: visible; }
#accounts.account-cockpit-tab .account-cockpit-section {
    width: min(1240px, 100%);
    max-width: none;
    margin: 0 auto;
}
.account-cockpit-heading {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: end;
    gap: 48px;
    margin-bottom: 31px;
}
.account-cockpit-kicker {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    color: #97a2ff;
    font-size: .65rem;
