@keyframes cockpitCapacityFlow { to { background-position: 200% 0; } }

/* The active identity is the visual core rather than another banner. */
#accounts.account-cockpit-tab .cockpit-core {
    grid-area: core;
    position: relative;
    min-width: 0;
    min-height: 625px;
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 0;
    margin: 0;
    padding: 22px 28px 24px;
    overflow: hidden;
    border: 0;
    border-radius: 0;
    background:
        radial-gradient(360px circle at 50% 36%, rgba(83, 100, 231, .18), transparent 60%),
