.cockpit-core-grid {
    position: absolute;
    inset: 0;
    opacity: .38;
    background-image: linear-gradient(rgba(139, 148, 255, .045) 1px, transparent 1px), linear-gradient(90deg, rgba(139, 148, 255, .045) 1px, transparent 1px);
    background-size: 28px 28px;
