}
.cockpit-core-rings { position: absolute; inset: 78px 0 auto; height: 300px; pointer-events: none; }
.cockpit-core-rings i {
    position: absolute;
    top: 50%;
    left: 50%;
    width: 260px;
    height: 260px;
    border: 1px solid rgba(112, 126, 238, .14);
    border-radius: 50%;
    transform: translate(-50%, -50%);
