    background: #7c8cff;
    box-shadow: 0 0 16px #7c8cff;
}
.cockpit-core-rings i:nth-child(2) { width: 330px; height: 330px; opacity: .55; animation-duration: 31s; animation-direction: reverse; }
.cockpit-core-rings i:nth-child(3) { width: 190px; height: 190px; opacity: .38; animation-duration: 15s; }
@keyframes cockpitRingSpin { from { transform: translate(-50%, -50%) rotate(0); } to { transform: translate(-50%, -50%) rotate(360deg); } }
.cockpit-core-topline {
