.cockpit-core-topline span i { width: 6px; height: 6px; border-radius: 50%; background: #4ade80; box-shadow: 0 0 11px rgba(74, 222, 128, .75); animation: motionStatusPulse 2.2s ease-in-out infinite; }
.cockpit-core:not(.has-active) .cockpit-core-topline span i { background: #fbbf24; box-shadow: 0 0 11px rgba(251, 191, 36, .65); }
.cockpit-core-topline em i { color: #7180ef; }
