@keyframes profilePrismStars { to { background-position: 58px 58px, 0 0, 0 0; } }
@keyframes profilePrismOrbitA { to { transform:translate(-50%,-50%) rotate(348deg); } }
@keyframes profilePrismOrbitB { to { transform:translate(-50%,-50%) rotate(391deg); } }
@keyframes profilePrismBeam { 0%,100% { opacity:.42; transform:translateX(-8px) scaleX(.94); } 50% { opacity:.82; transform:translateX(7px) scaleX(1.03); } }
@keyframes profilePrismFloat { 0%,100% { transform:translateY(0) rotate(-1.5deg); } 50% { transform:translateY(-7px) rotate(1.5deg); } }
@keyframes profilePrismShardA { 0%,100% { transform:translateY(0) rotate(-24deg); } 50% { transform:translateY(-9px) rotate(-17deg); } }
@keyframes profilePrismShardB { 0%,100% { transform:translateY(0) rotate(31deg); } 50% { transform:translateY(7px) rotate(24deg); } }
@keyframes profileCodeGrid { to { background-position:22px 22px,22px 22px,74px 74px; } }
@keyframes profileCodeScan { 0%,16% { transform:translateY(0); opacity:0; } 34% { opacity:1; } 78%,100% { transform:translateY(180px); opacity:0; } }
@keyframes profileCodeStatus { 50% { opacity:.45; transform:scale(.72); } }

