        linear-gradient(125deg,#29113a,#111936 48%,#0b2230);
}
body.light-theme .profile-cover[data-header="prism"]::after,
body.light-theme .profile-cover[data-header="code"]::after { background:linear-gradient(transparent,rgba(8,11,31,.58) 57%,rgba(7,9,24,.91)); }
body.light-theme .dashboard-modal.profile-wide .profile-cover[data-header="prism"] .profile-header,
