html.lite-mode .profile-code-reticle,
html.lite-mode .profile-code-window::before { display:none!important; }

/* ================================================================
   FINAL LAYOUT + MOTION STABILITY PASS
   Keeps the existing visual language while removing overlap, clipped
   mobile content and unnecessary full-surface paint work.
   ================================================================ */
html {
    scrollbar-gutter: stable;
}

html,
body {
    overflow-x: clip;
}

body {
    min-height: 100dvh;
}

.content-wrapper {
    width: 100%;
    max-width: 1600px;
    margin-left: auto;
    margin-right: auto;
}

.logo-container {
    min-width: 0;
    color: inherit;
    text-decoration: none;
}

.logo-container:focus-visible,
.nav-btn:focus-visible,
button:focus-visible,
a:focus-visible,
[role="button"]:focus-visible {
    outline: 2px solid #9aa5ff;
    outline-offset: 3px;
}

.ambient-light {
    filter: none !important;
    opacity: .14;
    contain: strict;
}

.ambient-light.purple {
    background: radial-gradient(circle, rgba(99, 102, 241, .9) 0%, rgba(99, 102, 241, .28) 36%, transparent 72%);
}

.ambient-light.blue {
    background: radial-gradient(circle, rgba(59, 130, 246, .85) 0%, rgba(59, 130, 246, .24) 36%, transparent 72%);
}

.ambient-light.pink {
    background: radial-gradient(circle, rgba(236, 72, 153, .8) 0%, rgba(236, 72, 153, .22) 36%, transparent 72%);
}

.features-section,
.dev-section,
.af-showcase,
.af-features-grid,
.support-knowledge-studio,
.forum-section {
    content-visibility: auto;
    contain-intrinsic-size: auto 780px;
}

.tab-content:not(.active-tab) *,
[role="dialog"][aria-hidden="true"] * {
    animation-play-state: paused !important;
}

html.motion-paused *,
html.motion-paused *::before,
html.motion-paused *::after {
    animation-play-state: paused !important;
}

body.nav-menu-open {
    overflow: hidden;
