h1,h2,h3,h4{font-family:var(--font-ui);text-wrap:balance}
p{ text-wrap:pretty }
code,kbd,pre,.dev-system-code,.support-code,.admin-inspector-id{font-family:var(--font-data)}
.fas,.far,.fab{flex-shrink:0;line-height:1}
button:disabled{cursor:not-allowed}
:where(button,a,input,select,textarea,[tabindex]):focus-visible{outline:2px solid var(--workspace-accent);outline-offset:4px}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.workspace-section-heading{display:flex;align-items:flex-start;gap:14px;margin:0 0 22px;text-align:left}
.workspace-section-heading>span{display:grid;place-items:center;width:42px;height:42px;flex:0 0 42px;border:1px solid var(--workspace-line);background:rgba(145,128,255,.09);border-radius:13px;color:var(--workspace-accent);font-size:17px}
