/* Keep the large account surface opaque while tabs change. Only small elements move. */
.dashboard-modal.profile-wide,
.dashboard-modal.profile-wide.store-wide,
.dashboard-modal.profile-wide.admin-wide{
  transition:transform 300ms cubic-bezier(.2,.8,.2,1),opacity 180ms ease,border-color 180ms ease !important;
}
.dashboard-modal.profile-wide.glass-modal{
  background:radial-gradient(circle at 8% -10%,rgba(112,123,240,.14),transparent 55%),linear-gradient(148deg,rgba(19,23,48,.94),rgba(6,9,22,.97)),#0b1020!important;
}
