.dashboard-modal.profile-wide.workspace-morphing::after{display:none !important}
.dashboard-modal.profile-wide.profile-replay{
  animation:accountShellSettle 280ms cubic-bezier(.2,.8,.2,1) both !important;
  will-change:transform;
}
@keyframes accountShellSettle{from{opacity:1;transform:translate3d(0,6px,0) scale(.995)}to{opacity:1;transform:translate3d(0,0,0) scale(1)}}
.dashboard-modal.profile-wide .ptab-content.ptab-enter,
.dashboard-modal.profile-wide.admin-wide .ptab-content.ptab-enter{
  animation:accountTabSettle 250ms cubic-bezier(.2,.8,.2,1) both !important;
  will-change:transform;
}
@keyframes accountTabSettle{from{opacity:1;transform:translate3d(0,7px,0)}to{opacity:1;transform:translate3d(0,0,0)}}
.dashboard-modal.profile-wide [data-ptab-content="my-profile"].ptab-enter > *,
.role-v2-card,.admin-v2-user,.admin-v2-review{animation:none !important;contain:none}
.role-v2-card,.admin-v2-user{backface-visibility:visible}
#profileView>.ptab-content{transform-origin:50% 0}
