.roles-v2-hero{position:relative;overflow:hidden;padding:31px 32px;background:radial-gradient(circle at 82% 16%,rgba(116,106,231,.2),transparent 36%),linear-gradient(115deg,#24254d,#101a33 68%,#102d39)}
