.roles-v2-grid{grid-template-columns:repeat(auto-fit,minmax(225px,1fr));gap:13px}
.role-v2-card{position:relative;gap:0;min-height:330px;padding:20px 19px 17px;border-radius:19px;background:linear-gradient(155deg,rgba(28,34,65,.98),rgba(14,20,40,.98));transition:transform 260ms cubic-bezier(.2,.8,.2,1),border-color 220ms ease,box-shadow 260ms ease !important}
.role-v2-card::before{content:"";position:absolute;top:0;left:22px;right:22px;height:2px;border-radius:0 0 8px 8px;background:var(--role-color);opacity:.7}
.role-v2-card.featured{border-color:rgba(170,155,255,.55);background:linear-gradient(155deg,#29254f,#161a39 62%,#131d37);box-shadow:0 12px 32px rgba(10,7,36,.28),inset 0 1px rgba(255,255,255,.05)}
.role-v2-card.featured::before{height:3px;opacity:1}
