.role-v2-card-name{margin-top:17px}
.role-v2-card h4{font-size:23px;font-weight:750;letter-spacing:-.035em}
.role-v2-card p{min-height:0;margin-top:5px;font-size:12px;line-height:1.55}
.role-v2-price-wrap{display:grid;gap:3px;margin:18px 0 14px}
.role-v2-price{color:#f4f0ff;font-size:18px;font-weight:750;letter-spacing:-.02em}
.role-v2-price-wrap small{color:var(--workspace-muted);font-size:10px}
.role-v2-capacity{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:15px}
.role-v2-capacity span{display:inline-flex;align-items:center;gap:5px;padding:6px 8px;border:1px solid rgba(178,183,240,.13);border-radius:7px;color:#cdd5ec;background:rgba(255,255,255,.035);font-size:10px;font-weight:600}
.role-v2-capacity i{color:var(--role-color)}
.role-v2-card ul{gap:8px;margin-bottom:20px;font-size:11px}
.role-v2-card li{line-height:1.4}
.role-v2-card button{align-self:end;min-height:42px;margin-top:auto;font-size:12px;font-weight:680}
.role-v2-card.featured button:not(:disabled){border-color:rgba(178,161,255,.55);background:linear-gradient(100deg,#7969dc,#625bd0)}
