/* A single quiet material language for the site header. */
.navbar.glass-nav,
.navbar.glass-nav.is-scrolled {
    min-height: 82px;
    padding-block: 11px;
    background: linear-gradient(105deg, rgba(24,29,53,.86), rgba(12,17,34,.83) 48%, rgba(15,22,41,.88)) !important;
    border-bottom: 1px solid rgba(195,207,255,.16);
    box-shadow: 0 14px 36px rgba(2,5,19,.22), inset 0 1px rgba(255,255,255,.07);
    -webkit-backdrop-filter: blur(26px) saturate(105%);
    backdrop-filter: blur(26px) saturate(105%);
    transition: transform 340ms cubic-bezier(.22,.8,.3,1), background-color 240ms ease, box-shadow 240ms ease;
}
.navbar.glass-nav.is-scrolled {
    background: linear-gradient(105deg, rgba(23,28,51,.93), rgba(10,15,31,.92) 52%, rgba(13,19,37,.94)) !important;
    box-shadow: 0 12px 32px rgba(2,5,19,.29), inset 0 1px rgba(255,255,255,.07);
}
.navbar.glass-nav::before {
    content: '';
    position: absolute;
    inset: 0 0 auto;
    height: 1px;
    pointer-events: none;
    background: linear-gradient(90deg, transparent 8%, rgba(171,184,255,.31) 25%, rgba(255,255,255,.12) 60%, transparent 92%);
}

/* The logo is a home link with a restrained illuminated frame. */
.navbar .logo-container {
    width: fit-content;
    gap: 11px;
    transform: none;
    text-decoration: none;
}
.navbar .logo-mark {
    display: grid;
    place-items: center;
    flex: none;
    width: 50px;
    height: 50px;
    border: 1px solid rgba(170,185,255,.21);
    border-radius: 16px;
    background: linear-gradient(145deg, rgba(113,127,236,.15), rgba(255,255,255,.015) 62%);
    box-shadow: inset 0 1px rgba(255,255,255,.11), 0 6px 19px rgba(1,4,17,.2);
    transition: border-color 280ms ease, background-color 280ms ease, box-shadow 280ms ease;
}
.navbar .logo-img-custom {
    width: 43px;
    height: 43px;
    filter: drop-shadow(0 2px 7px rgba(114,126,255,.28));
    transition: transform 420ms cubic-bezier(.22,.8,.3,1), filter 280ms ease;
}
.navbar .logo-container:hover { transform: none; }
.navbar .logo-container:hover .logo-mark {
    border-color: rgba(181,190,255,.47);
    box-shadow: inset 0 1px rgba(255,255,255,.18), 0 7px 22px rgba(86,95,220,.16);
}
.navbar .logo-container:hover .logo-img-custom {
    transform: scale(1.055);
    filter: drop-shadow(0 3px 9px rgba(135,145,255,.36));
}
.navbar .logo-lockup { display: flex; flex-direction: column; align-items: flex-start; min-width: 0; }
.navbar .logo-text {
    display: block;
    color: #f7f8ff;
    font-size: 1.36rem;
    font-weight: 800;
    line-height: 1.03;
    letter-spacing: -.035em;
    text-shadow: none;
}
.navbar .logo-container:hover .logo-text { text-shadow: none; }
.navbar .logo-lockup small {
    margin-top: 4px;
    color: #9ca9d4;
    font-size: .59rem;
    font-weight: 800;
    line-height: 1;
    letter-spacing: .23em;
}

/* A small sliding surface follows the active tab, including rapid changes. */
.navbar.glass-nav .nav-links-container.glass {
    position: relative;
    align-items: center;
    gap: 2px;
    padding: 5px;
    border: 1px solid rgba(171,187,240,.15);
    border-radius: 18px;
    background: rgba(35,43,68,.47) !important;
    box-shadow: inset 0 1px rgba(255,255,255,.06), 0 4px 16px rgba(1,4,19,.12);
    -webkit-backdrop-filter: blur(14px) saturate(95%);
    backdrop-filter: blur(14px) saturate(95%);
}
.navbar .nav-active-indicator {
    position: absolute;
    top: 5px;
    bottom: 5px;
    left: 0;
    z-index: 0;
    width: 0;
    border: 1px solid rgba(173,183,255,.23);
    border-radius: 13px;
    opacity: 0;
    pointer-events: none;
    background: linear-gradient(145deg, rgba(117,125,245,.32), rgba(83,104,204,.19));
    box-shadow: inset 0 1px rgba(255,255,255,.12), 0 4px 13px rgba(61,66,169,.16);
}
.navbar .nav-active-indicator.is-ready {
    opacity: 1;
    transition: transform 430ms cubic-bezier(.22,.8,.25,1), width 430ms cubic-bezier(.22,.8,.25,1), opacity 180ms ease;
}
.navbar .nav-links-container .nav-btn {
    z-index: 1;
    flex: none;
    min-height: 42px;
    padding: 9px clamp(9px,1vw,15px);
    gap: 8px;
    border: 1px solid transparent;
    border-radius: 13px;
    color: #aeb9d5;
    font-size: .83rem;
    font-weight: 650;
    white-space: nowrap;
    overflow: visible;
    transform: none;
    transition: color 220ms ease, background-color 220ms ease;
}
.navbar .nav-links-container .nav-btn::before { display: none; }
.navbar .nav-links-container .nav-btn i {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex: 0 0 16px;
    width: 16px;
    line-height: 1;
    transition: color 220ms ease, transform 300ms cubic-bezier(.22,.8,.3,1);
}
.navbar .nav-links-container .nav-btn:hover {
    color: #fff;
    background: rgba(165,177,255,.09);
    box-shadow: none;
    transform: none;
}
.navbar .nav-links-container .nav-btn:hover i { transform: translateY(-1px); }
.navbar .nav-links-container .nav-btn.active {
    color: #f9faff;
    border-color: transparent;
    background: transparent;
    box-shadow: none;
    transform: none;
}
.navbar .nav-links-container .nav-btn.active i {
    color: #b9beff;
    animation: none;
}

