.navbar .account-copy { display: flex; flex: 1; flex-direction: column; align-items: flex-start; min-width: 0; text-align: left; }
.navbar .account-copy small { color: #9faed2; font-size: .58rem; font-weight: 800; line-height: 1.3; letter-spacing: .12em; }
