}
@media (prefers-reduced-motion: reduce) {
    .tab-content.route-enter,
    .tab-content.route-enter :is(.hero-text-block,.hero-visual-block,.account-cockpit-heading-copy,.account-cockpit-summary,.updates-heading-copy,.updates-featured,.dev-hero-copy,.dev-profile,.af-hero h2,.af-hero > p,.support-hero-copy,.support-response-card) { animation: none !important; }
    .animate-on-scroll { transition: none !important; opacity: 1 !important; transform: none !important; }
}
