/* Shared viewport and palette finish. Keep these rules last in the source manifest. */
:root { color-scheme: dark; }
body.light-theme {
    color-scheme: light;
    --bg-dark: #f4f7fd;
    --text: #1b2743;
    --text-muted: #52617f;
    --glass-border: rgba(57, 77, 128, .16);
    --day-ink: #202d4b;
    --day-heading: #17233f;
    --day-copy: #4f5f7c;
    --day-muted: #62708d;
    --day-line: rgba(57, 77, 128, .17);
    --day-surface: #fff;
    --day-surface-soft: #f7f9fd;
    background: #f4f7fd;
}
body.light-theme .bg-gradient-overlay {
    background: radial-gradient(55% 45% at 8% 6%, rgba(125, 142, 224, .13), transparent 75%),
        radial-gradient(46% 38% at 92% 68%, rgba(45, 166, 191, .09), transparent 76%);
}
body.light-theme .vignette { opacity: .35; }
body.light-theme .ambient-light { opacity: .09; }
body.light-theme .light-bg-shapes .lbs { opacity: .2; }
body.light-theme :is(#home,#accounts,#updates,#development,#advanced-features,#support) {
    color: var(--day-ink);
}
body.light-theme :is(#home,#updates,#development,#advanced-features,#support) .text-gradient {
    background: linear-gradient(110deg, #394da4 0%, #5749b4 48%, #9b326f 100%);
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
}
