body.light-theme :is(#home,#updates,#development,#advanced-features,#support) :is(input,textarea)::placeholder { color: #687797; opacity: 1; }

/* The palette control belongs to the main navigation, including for guests. */
.navbar .nav-actions {
    display: flex;
    align-items: center;
    justify-self: end;
    gap: 8px;
    min-width: 0;
}
.navbar .nav-theme-toggle {
    position: relative;
    order: -1;
    display: grid;
    place-items: center;
    flex: 0 0 46px;
    width: 46px;
    height: 46px;
    margin-left: 0;
    border: 1px solid rgba(171,187,240,.2);
    border-radius: 15px;
    color: #cad3ff;
    background: rgba(53,62,91,.3);
    box-shadow: inset 0 1px rgba(255,255,255,.07);
    cursor: pointer;
    transition: color .25s ease, background-color .25s ease, border-color .25s ease, transform .3s cubic-bezier(.2,.8,.25,1);
}
.navbar .nav-theme-toggle:hover { color: #fff; border-color: rgba(170,183,255,.48); background: rgba(91,104,160,.27); transform: translateY(-2px); }
.navbar .nav-theme-toggle:focus-visible { outline: 2px solid #9fa9ff; outline-offset: 3px; }
.nav-theme-toggle i { position: absolute; font-size: 1.1rem; transition: opacity .28s ease, transform .42s cubic-bezier(.2,.8,.25,1); }
.nav-theme-toggle .theme-icon-sun { opacity: 1; transform: rotate(0) scale(1); }
.nav-theme-toggle .theme-icon-moon { opacity: 0; transform: rotate(-65deg) scale(.45); }
body.light-theme .nav-theme-toggle .theme-icon-sun { opacity: 0; transform: rotate(65deg) scale(.45); }
body.light-theme .nav-theme-toggle .theme-icon-moon { opacity: 1; transform: rotate(0) scale(1); }
body.light-theme .navbar .nav-theme-toggle { color: #424d9d; border-color: rgba(77,91,154,.2); background: rgba(255,255,255,.72); box-shadow: inset 0 1px #fff, 0 5px 16px rgba(68,85,142,.08); }
body.light-theme .navbar .nav-theme-toggle:hover { color: #27347d; border-color: rgba(69,83,176,.42); background: #fff; }

/* A short reveal keeps gradients and illustrations coherent while changing palette. */
::view-transition { pointer-events: none; }
::view-transition-old(root) { animation: none; }
::view-transition-new(root) { animation: themeReveal .56s cubic-bezier(.18,.8,.25,1) both; }
@keyframes themeReveal {
    from { clip-path: circle(0 at var(--theme-origin-x, 50%) var(--theme-origin-y, 50%)); }
    to { clip-path: circle(var(--theme-radius, 150vmax) at var(--theme-origin-x, 50%) var(--theme-origin-y, 50%)); }
}
body.theme-switching :is(.navbar,.nav-links-container,.dashboard-modal,.acc-panel,.timeline-card,.feature-card,.support-channel,.faq-item) {
    transition: color .38s ease, background-color .42s ease, border-color .42s ease, box-shadow .42s ease;
}

/* Authentication forms must remain reachable on short phone and landscape viewports. */
.dashboard-modal.glass-modal:not(.profile-wide) {
    overflow-x: hidden;
    overflow-y: auto;
    overscroll-behavior: contain;
}

/* Narrow screens must keep every route and dialog reachable without page clipping. */
.content-wrapper, .tab-content, .tab-content > *, .dashboard-modal, .dashboard-view { min-width: 0; }
:is(.updates-toolbar,.updates-header,.dev-hero,.dev-systems-layout,.af-hero,.support-knowledge-studio,.identity-cockpit) > * { min-width: 0; }
:is(.tab-content,.dashboard-modal) :is(h1,h2,h3,h4,p,strong) { overflow-wrap: break-word; }

