/* Site atmosphere and the product preview are the final visual layer. */
body {
    background: radial-gradient(80% 70% at 68% 0%, #121b45 0%, #080e25 52%, #050916 100%);
}
.bg-gradient-overlay {
    overflow: hidden;
    background:
        radial-gradient(54% 64% at 4% 12%, rgba(95, 76, 207, .27), transparent 72%),
        radial-gradient(53% 57% at 93% 20%, rgba(36, 130, 216, .24), transparent 74%),
        radial-gradient(44% 58% at 56% 82%, rgba(79, 73, 183, .13), transparent 75%),
        linear-gradient(130deg, rgba(11, 19, 47, .46), rgba(4, 9, 25, .15) 58%, rgba(10, 27, 54, .4));
    animation: siteAuroraDrift 24s ease-in-out infinite alternate;
}
.bg-gradient-overlay::before {
    content: none;
}
.bg-gradient-overlay::after {
    content: "";
    position: absolute;
    inset: -12%;
    background:
        radial-gradient(circle at 12% 22%, rgba(160, 174, 255, .46) 0 1px, transparent 2px),
        radial-gradient(circle at 70% 15%, rgba(108, 205, 250, .46) 0 1px, transparent 2px),
        radial-gradient(circle at 52% 79%, rgba(210, 163, 255, .38) 0 1px, transparent 2px),
        radial-gradient(ellipse 44% 28% at 55% 10%, rgba(108, 100, 220, .11), transparent 82%);
    background-size: 227px 193px, 319px 283px, 397px 307px, 100% 100%;
    opacity: .72;
    animation: siteDustFloat 32s ease-in-out infinite alternate;
}
.vignette {
    background: radial-gradient(ellipse 82% 78% at 50% 40%, transparent 28%, rgba(3, 6, 19, .25) 76%, rgba(3, 6, 17, .56));
}
.ambient-light { width: min(48vw, 710px); height: min(48vw, 710px); opacity: .38; filter: none; }
.ambient-light.purple { background: radial-gradient(circle, rgba(111, 92, 232, .76), rgba(89, 73, 205, .3) 35%, rgba(89, 73, 205, .07) 61%, transparent 75%); }
.ambient-light.blue { background: radial-gradient(circle, rgba(34, 145, 215, .72), rgba(28, 117, 194, .28) 35%, rgba(28, 117, 194, .06) 61%, transparent 75%); }
.ambient-light.pink { background: radial-gradient(circle, rgba(181, 76, 177, .68), rgba(150, 59, 168, .28) 35%, rgba(150, 59, 168, .06) 61%, transparent 75%); }
body::before {
    background: radial-gradient(560px circle at var(--pointer-x) var(--pointer-y), rgba(115, 134, 255, .12), transparent 72%);
}
body.light-theme {
    background: radial-gradient(75% 65% at 52% 0%, #fcfdff, #f1f5ff 55%, #eaf1fc 100%);
}
body.light-theme .bg-gradient-overlay {
    background:
        radial-gradient(56% 57% at 3% 13%, rgba(143, 118, 229, .17), transparent 73%),
        radial-gradient(54% 62% at 97% 23%, rgba(78, 170, 224, .16), transparent 74%),
        radial-gradient(50% 50% at 55% 88%, rgba(116, 136, 225, .1), transparent 78%),
        linear-gradient(140deg, rgba(255, 255, 255, .5), transparent 53%);
}
body.light-theme .bg-gradient-overlay::after { opacity: .45; mix-blend-mode: multiply; }
body.light-theme .vignette {
    background: radial-gradient(ellipse 84% 78% at 50% 40%, transparent 32%, rgba(119, 138, 196, .04) 78%, rgba(101, 120, 181, .1));
}
body.light-theme .ambient-light { opacity: .13; filter: none; mix-blend-mode: multiply; }
body.light-theme::before {
    background: radial-gradient(540px circle at var(--pointer-x) var(--pointer-y), rgba(91, 111, 206, .08), transparent 72%);
}
@keyframes siteAuroraDrift { to { transform: translate3d(1.2%, -1.3%, 0) scale(1.035); } }
@keyframes siteDustFloat { to { transform: translate3d(-2.5%, 2%, 0); } }

