/* Role identity is expressed through light and texture, without literal emblems. */
.dashboard-modal.profile-wide .profile-cover {
  --header-a: #8880ff;
  --header-b: #bb83e9;
  --header-c: #b4b6ff;
  --header-surface:
    radial-gradient(ellipse 43% 110% at 78% 40%, rgba(123, 113, 246, .31), transparent 75%),
    radial-gradient(ellipse 58% 140% at 94% 108%, rgba(188, 102, 215, .20), transparent 77%),
    linear-gradient(112deg, #10142c, #121530 58%, #201534);
  min-height: 220px;
  border: 1px solid color-mix(in srgb, var(--header-a) 29%, rgba(255, 255, 255, .12));
  border-radius: 21px;
  background: var(--header-surface) !important;
  box-shadow: inset 0 1px rgba(255, 255, 255, .13), 0 16px 38px rgba(2, 3, 18, .26);
}
.dashboard-modal.profile-wide .profile-cover[data-header="archive"] {
  --header-a: #69d0bd;
  --header-b: #79b8cd;
  --header-c: #a9e8d7;
  --header-surface:
    radial-gradient(ellipse 48% 120% at 82% 46%, rgba(70, 180, 159, .22), transparent 75%),
    linear-gradient(122deg, transparent 52%, rgba(120, 224, 205, .045) 52.2%, transparent 53%),
    linear-gradient(112deg, #0d1b27, #102532 60%, #19313d);
}
.dashboard-modal.profile-wide .profile-cover[data-header="solar"] {
