@media (max-width: 1060px) {
  .roles-v2-hero { grid-template-columns: minmax(0,1fr) 175px; }
  .roles-v2-hero-display { width: 170px; height: 170px; }
  .roles-v2-display-ring.ring-one { width: 166px; height: 100px; }
  .roles-v2-display-ring.ring-two { width: 112px; height: 160px; }
  .roles-v2-display-gem { width: 92px; height: 92px; }
  .roles-v2-display-gem i { font-size: 37px; }
  .roles-v2-grid { grid-template-columns: repeat(2,minmax(0,1fr)); }
}
@media (max-width: 680px) {
  .roles-v2-hero { grid-template-columns: 1fr; min-height: 0; padding: 23px; }
  .roles-v2-hero h2 { font-size: clamp(34px,8vw,44px); }
  .roles-v2-hero-display { position: absolute; top: 15px; right: -26px; width: 144px; height: 144px; opacity: .35; }
  .roles-v2-hero-display small { display: none; }
  .roles-v2-current { position: relative; right: auto; bottom: auto; grid-column: 1; width: 100%; max-width: 280px; margin-top: 7px; }
  .roles-v2-toolbar { align-items: stretch; flex-direction: column; }
  .roles-v2-cycle { align-self: flex-start; }
  .roles-v2-grid { grid-template-columns: repeat(2,minmax(0,1fr)); }
  .role-v2-card { padding-inline: 14px; }
  .role-v2-art { margin-inline: -14px; }
  .roles-v2-checkout { grid-template-columns: 40px minmax(0,1fr) auto; padding-right: 23px; }
  .roles-v2-checkout-total { grid-column: 2; justify-items: start; }
  .roles-v2-confirm { grid-column: 3; grid-row: 1 / 3; }
}
@media (max-width: 510px) {
  .roles-v2-sectionline span:last-child { display: none; }
  .roles-v2-entitlements { grid-template-columns: 1fr; }
  .roles-v2-grid { grid-template-columns: 1fr; }
  .role-v2-card { min-height: 0; }
  .role-v2-art { flex-basis: 115px; height: 115px; }
  .role-v2-card-name { min-height: 0; }
  .roles-v2-checkout { grid-template-columns: 40px minmax(0,1fr); gap: 8px 11px; }
  .roles-v2-checkout-total { grid-column: 2; }
  .roles-v2-confirm { grid-column: 1 / -1; grid-row: auto; }
}
@media (prefers-reduced-motion: reduce) {
  .role-v2-card,.role-v2-art-emblem,.role-v2-art-orbit,.role-v2-card::after,.role-v2-card>button i:last-child { animation: none; transition: none; }
  .role-v2-card:hover,.role-v2-card:focus-within,.role-v2-card:active { transform: none; }
  .role-v2-card:hover::after { opacity: 0; }
}
@media (hover: none) { .role-v2-card::after { display: none; } }
html.lite-mode .role-v2-card,html.lite-mode .role-v2-art-emblem,html.lite-mode .role-v2-art-orbit,html.lite-mode .role-v2-card::after { animation: none; transition: none; }
html.lite-mode .role-v2-card::after { display: none; }
